insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6ba4d18c-1f79-57e3-8c50-911ff2d2e25f', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '134', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ حَيٍّ هُوَ الْحَسَنُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَامِرٍ الْبَجَلِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي نُعْمٍ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسَحَ عَلَى الْخُفَّيْنِ فَقُلْتُ يَا رَسُولَ اللَّهِ أَنَسِيتَ قَالَ بَلْ أَنْتَ نَسِيتَ بِهَذَا أَمَرَنِي رَبِّي عَزَّ وَجَلَّ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f2928584-fc54-59bd-be9d-ac9d473c6958', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '135', '‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏وَحَمَّادٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الْجَدَلِيِّ ‏ ‏عَنْ ‏ ‏خُزَيْمَةَ بْنِ ثَابِتٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمَسْحُ عَلَى الْخُفَّيْنِ لِلْمُسَافِرِ ثَلَاثَةُ أَيَّامٍ وَلِلْمُقِيمِ يَوْمٌ وَلَيْلَةٌ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏رَوَاهُ ‏ ‏مَنْصُورُ بْنُ الْمُعْتَمِرِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏بِإِسْنَادِهِ قَالَ فِيهِ ‏ ‏وَلَوْ اسْتَزَدْنَاهُ لَزَادَنَا ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e1bdfe9b-2b8b-55f1-a214-fa59c680164a', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '136', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ مَعِينٍ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الرَّبِيعِ بْنِ طَارِقٍ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ رَزِينٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ قَطَنٍ ‏ ‏عَنْ ‏ ‏أُبَيِّ بْنِ عِمَارَةَ ‏ ‏قَالَ ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏وَكَانَ قَدْ صَلَّى مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْقِبْلَتَيْنِ أَنَّهُ قَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَمْسَحُ عَلَى الْخُفَّيْنِ قَالَ نَعَمْ قَالَ يَوْمًا قَالَ يَوْمًا قَالَ وَيَوْمَيْنِ قَالَ وَيَوْمَيْنِ قَالَ وَثَلَاثَةً قَالَ نَعَمْ وَمَا شِئْتَ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏رَوَاهُ ‏ ‏ابْنُ أَبِي مَرْيَمَ الْمِصْرِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ رَزِينٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عُبَادَةَ بْنِ نُسِيٍّ ‏ ‏عَنْ ‏ ‏أُبَيِّ بْنِ عِمَارَةَ ‏ ‏قَالَ فِيهِ ‏ ‏حَتَّى بَلَغَ سَبْعًا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ وَمَا بَدَا لَكَ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَقَدْ اخْتُلِفَ فِي إِسْنَادِهِ وَلَيْسَ هُوَ بِالْقَوِيِّ ‏ ‏وَرَوَاهُ ‏ ‏ابْنُ أَبِي مَرْيَمَ ‏ ‏وَيَحْيَى بْنُ إِسْحَقَ السَّيْلَحِينِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَيَّوبَ ‏ ‏وَقَدْ اخْتُلِفَ فِي إِسْنَادِهِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ee961144-8a9c-5b44-aa2a-80236cd93b29', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '137', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏عَنْ ‏ ‏وَكِيعٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي قَيْسٍ الْأَوْدِيِّ هُوَ عَبْدُ الرَّحْمَنِ بْنُ ثَرْوَانَ ‏ ‏عَنْ ‏ ‏هُزَيْلِ بْنِ شُرَحْبِيلَ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ وَمَسَحَ عَلَى الْجَوْرَبَيْنِ وَالنَّعْلَيْنِ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏كَانَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏لَا يُحَدِّثُ بِهَذَا الْحَدِيثِ ‏ ‏لِأَنَّ الْمَعْرُوفَ عَنْ ‏ ‏الْمُغِيرَةِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسَحَ عَلَى الْخُفَّيْنِ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَرُوِيَ ‏ ‏هَذَا أَيْضًا ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ مَسَحَ عَلَى الْجَوْرَبَيْنِ ‏ ‏وَلَيْسَ بِالْمُتَّصِلِ وَلَا بِالْقَوِيِّ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَمَسَحَ عَلَى الْجَوْرَبَيْنِ ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏وَابْنُ مَسْعُودٍ ‏ ‏وَالْبَرَاءُ بْنُ عَازِبٍ ‏ ‏وَأَنَسُ بْنُ مَالِكٍ ‏ ‏وَأَبُو أُمَامَةَ ‏ ‏وَسَهْلُ بْنُ سَعْدٍ ‏ ‏وَعَمْرُو بْنُ حُرَيْثٍ ‏ ‏وَرُوِيَ ‏ ‏ذَلِكَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏وَابْنِ عَبَّاسٍ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c487d4c8-681f-52c6-a6e4-d9317ddee199', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '138', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏وَعَبَّادُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏عَبَّادٌ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَوْسُ بْنُ أَبِي أَوْسٍ الثَّقَفِيُّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ وَمَسَحَ عَلَى نَعْلَيْهِ وَقَدَمَيْهِ ‏ ‏وَقَالَ ‏ ‏عَبَّادٌ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى ‏ ‏كِظَامَةَ ‏ ‏قَوْمٍ ‏ ‏يَعْنِي ‏ ‏الْمِيضَأَةَ ‏ ‏وَلَمْ يَذْكُرْ ‏ ‏مُسَدَّدٌ ‏ ‏الْمِيضَأَةَ ‏ ‏وَالْكِظَامَةَ ‏ ‏ثُمَّ اتَّفَقَا ‏ ‏فَتَوَضَّأَ وَمَسَحَ عَلَى نَعْلَيْهِ وَقَدَمَيْهِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5153267f-6210-516d-8247-acd05350e281', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '139', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّبَّاحِ الْبَزَّازُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏قَالَ ذَكَرَهُ ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَمْسَحُ عَلَى الْخُفَّيْنِ ‏ ‏و قَالَ ‏ ‏غَيْرُ ‏ ‏مُحَمَّدٍ ‏ ‏عَلَى ظَهْرِ الْخُفَّيْنِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f425ad68-6af2-5441-bd57-0513cf34c598', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '140', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصٌ يَعْنِي ابْنَ غِيَاثٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَبْدِ خَيْرٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏لَوْ كَانَ الدِّينُ بِالرَّأْيِ لَكَانَ أَسْفَلُ الْخُفِّ أَوْلَى بِالْمَسْحِ مِنْ أَعْلَاهُ وَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَى ظَاهِرِ خُفَّيْهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏بِإِسْنَادِهِ ‏ ‏بِهَذَا الْحَدِيثِ قَالَ مَا كُنْتُ ‏ ‏أَرَى بَاطِنَ الْقَدَمَيْنِ إِلَّا أَحَقَّ بِالْغَسْلِ حَتَّى رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَى ظَهْرِ خُفَّيْهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏بِهَذَا الْحَدِيثِ قَالَ لَوْ كَانَ الدِّينُ بِالرَّأْيِ لَكَانَ بَاطِنُ الْقَدَمَيْنِ أَحَقَّ بِالْمَسْحِ مِنْ ظَاهِرِهِمَا وَقَدْ مَسَحَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ظَهْرِ خُفَّيْهِ ‏ ‏وَرَوَاهُ ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏بِإِسْنَادِهِ قَالَ ‏ ‏كُنْتُ ‏ ‏أَرَى أَنَّ بَاطِنَ الْقَدَمَيْنِ أَحَقُّ بِالْمَسْحِ مِنْ ظَاهِرِهِمَا حَتَّى رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَى ظَاهِرِهِمَا ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏يَعْنِي الْخُفَّيْنِ ‏ ‏وَرَوَاهُ ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏كَمَا رَوَاهُ ‏ ‏وَكِيعٌ ‏ ‏وَرَوَاهُ ‏ ‏أَبُو السَّوْدَاءِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبْدِ خَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ رَأَيْتُ ‏ ‏عَلِيًّا ‏ ‏تَوَضَّأَ فَغَسَلَ ظَاهِرَ قَدَمَيْهِ وَقَالَ لَوْلَا أَنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُهُ وَسَاقَ الْحَدِيثَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d0f862b2-88dc-5967-aa21-29e87048f82c', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '141', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ مَرْوَانَ ‏ ‏وَمَحْمُودُ بْنُ خَالِدٍ الدِّمَشْقِيُّ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْوَلِيدُ ‏ ‏قَالَ ‏ ‏مَحْمُودٌ ‏ ‏أَخْبَرَنَا ‏ ‏ثَوْرُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏رَجَاءِ بْنِ حَيْوَةَ ‏ ‏عَنْ ‏ ‏كَاتِبِ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏وَضَّأْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏فَمَسَحَ أَعْلَى الْخُفَّيْنِ وَأَسْفَلَهُمَا ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَبَلَغَنِي أَنَّهُ لَمْ يَسْمَعْ ‏ ‏ثَوْرُ ‏ ‏هَذَا الْحَدِيثَ مِنْ ‏ ‏رَجَاءٍ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('19d0688f-0c59-5b32-81db-7634f17a086c', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '142', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ كَثِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ هُوَ الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ بْنِ الْحَكَمِ الثَّقَفِيِّ ‏ ‏أَوْ ‏ ‏الْحَكَمِ بْنِ سُفْيَانَ الثَّقَفِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا بَالَ يَتَوَضَّأُ ‏ ‏وَيَنْتَضِحُ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَافَقَ ‏ ‏سُفْيَانَ ‏ ‏جَمَاعَةٌ عَلَى هَذَا الْإِسْنَادِ ‏ ‏و قَالَ ‏ ‏بَعْضُهُمْ ‏ ‏الْحَكَمُ ‏ ‏أَوْ ‏ ‏ابْنُ الْحَكَمِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('80e1a270-a7af-54d7-8cd1-9a5e94becc87', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '143', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِسْمَعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ هُوَ ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏ثَقِيفٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَالَ ثُمَّ ‏ ‏نَضَحَ ‏ ‏فَرْجَهُ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('34bf6d11-25ab-54f4-8f4b-06c0db1a5af0', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '144', '‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ الْمُهَاجِرِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏أَوْ ‏ ‏ابْنِ الْحَكَمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَالَ ثُمَّ تَوَضَّأَ ‏ ‏وَنَضَحَ ‏ ‏فَرْجَهُ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('97b09a08-f693-52b1-a124-a42619691140', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '145', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ سَعِيدٍ الْهَمْدَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏سَمِعْتُ ‏ ‏مُعَاوِيَةَ يَعْنِي ابْنَ صَالِحٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُدَّامَ أَنْفُسِنَا نَتَنَاوَبُ الرِّعَايَةَ رِعَايَةَ إِبِلِنَا فَكَانَتْ عَلَيَّ رِعَايَةُ الْإِبِلِ ‏ ‏فَرَوَّحْتُهَا ‏ ‏بِالْعَشِيِّ فَأَدْرَكْتُ رَسُولَ اللَّهِ يَخْطُبُ النَّاسَ فَسَمِعْتُهُ يَقُولُ ‏ ‏مَا مِنْكُمْ مِنْ أَحَدٍ يَتَوَضَّأُ فَيُحْسِنُ الْوُضُوءَ ثُمَّ يَقُومُ فَيَرْكَعُ رَكْعَتَيْنِ يُقْبِلُ عَلَيْهِمَا بِقَلْبِهِ وَوَجْهِهِ إِلَّا قَدْ ‏ ‏أَوْجَبَ ‏ ‏فَقُلْتُ ‏ ‏بَخٍ بَخٍ ‏ ‏مَا أَجْوَدَ هَذِهِ فَقَالَ رَجُلٌ مِنْ بَيْنِ يَدَيَّ الَّتِي قَبْلَهَا يَا ‏ ‏عُقْبَةُ ‏ ‏أَجْوَدُ مِنْهَا فَنَظَرْتُ فَإِذَا هُوَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏فَقُلْتُ مَا هِيَ يَا ‏ ‏أَبَا حَفْصٍ ‏ ‏قَالَ إِنَّهُ قَالَ آنِفًا قَبْلَ أَنْ تَجِيءَ ‏ ‏مَا مِنْكُمْ مِنْ أَحَدٍ يَتَوَضَّأُ فَيُحْسِنُ الْوُضُوءَ ثُمَّ يَقُولُ حِينَ يَفْرُغُ مِنْ وُضُوئِهِ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ إِلَّا فُتِحَتْ لَهُ أَبْوَابُ الْجَنَّةِ الثَّمَانِيَةُ يَدْخُلُ مِنْ أَيِّهَا شَاءَ ‏ ‏قَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏وَحَدَّثَنِي ‏ ‏رَبِيعَةُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحُسَيْنُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ الْمُقْرِئُ ‏ ‏عَنْ ‏ ‏حَيْوَةَ وَهُوَ ابْنُ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِي عَقِيلٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَمِّهِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ وَلَمْ يَذْكُرْ أَمْرَ الرِّعَايَةِ قَالَ عِنْدَ قَوْلِهِ فَأَحْسَنَ الْوُضُوءَ ثُمَّ رَفَعَ بَصَرَهُ إِلَى السَّمَاءِ فَقَالَ وَسَاقَ الْحَدِيثَ بِمَعْنَى حَدِيثِ ‏ ‏مُعَاوِيَةَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fd1d3886-7bc0-5e33-b524-bedca26a0f2a', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '146', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَامِرٍ الْبَجَلِيِّ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏هُوَ ‏ ‏أَبُو أَسَدِ بْنُ عَمْرٍو ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏عَنْ الْوُضُوءِ فَقَالَ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ لِكُلِّ صَلَاةٍ وَكُنَّا نُصَلِّي الصَّلَوَاتِ بِوُضُوءٍ وَاحِدٍ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8ef7a028-30f3-59a8-9a1a-e0fcd446bc07', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '147', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏عَلْقَمَةُ بْنُ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْفَتْحِ خَمْسَ صَلَوَاتٍ بِوُضُوءٍ وَاحِدٍ وَمَسَحَ عَلَى خُفَّيْهِ فَقَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏إِنِّي رَأَيْتُكَ صَنَعْتَ الْيَوْمَ شَيْئًا لَمْ تَكُنْ تَصْنَعُهُ قَالَ عَمْدًا صَنَعْتُهُ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4b88c106-cb19-5319-85d9-5cd1d4fa9140', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '148', '‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ حَازِمٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏قَتَادَةَ بْنَ دِعَامَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ رَجُلًا جَاءَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ تَوَضَّأَ وَتَرَكَ عَلَى قَدَمِهِ مِثْلَ مَوْضِعِ الظُّفْرِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ارْجِعْ فَأَحْسِنْ وُضُوءَكَ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏هَذَا الْحَدِيثُ لَيْسَ بِمَعْرُوفٍ عَنْ ‏ ‏جَرِيرِ بْنِ حَازِمٍ ‏ ‏وَلَمْ يَرْوِهِ إِلَّا ‏ ‏ابْنُ وَهْبٍ ‏ ‏وَحْدَهُ ‏ ‏وَقَدْ ‏ ‏رُوِيَ عَنْ ‏ ‏مَعْقِلِ بْنِ عُبَيْدِ اللَّهِ الْجَزَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ قَالَ ارْجِعْ فَأَحْسِنْ وُضُوءَكَ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏وَحُمَيْدٌ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَعْنَى ‏ ‏قَتَادَةَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5ef1de86-d452-5a04-9f5d-413b26c214d4', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '149', '‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏عَنْ ‏ ‏بُجَيْرٍ هُوَ ابْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏بَعْضِ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى رَجُلًا يُصَلِّ وَفِي ظَهْرِ قَدَمِهِ ‏ ‏لُمْعَةٌ ‏ ‏قَدْرُ الدِّرْهَمِ لَمْ يُصِبْهَا الْمَاءُ ‏ ‏فَأَمَرَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُعِيدَ الْوُضُوءَ وَالصَّلَاةَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('af0b8969-3c2c-56f9-a675-71f74187a7e8', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '150', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَمُحَمَّدُ بْنُ أَحْمَدَ بْنِ أُبَيِّ بْنِ خَلَفٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏وَعَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ ‏ ‏شُكِيَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرَّجُلُ يَجِدُ الشَّيْءَ فِي الصَّلَاةِ حَتَّى يُخَيَّلَ إِلَيْهِ فَقَالَ ‏ ‏لَا ‏ ‏يَنْفَتِلْ ‏ ‏حَتَّى يَسْمَعَ صَوْتًا أَوْ يَجِدَ رِيحًا ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('468c367b-c11e-521f-b8c7-46a1e33dba10', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '151', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ فِي الصَّلَاةِ فَوَجَدَ حَرَكَةً فِي دُبُرِهِ ‏ ‏أَحْدَثَ ‏ ‏أَوْ لَمْ ‏ ‏يُحْدِثْ ‏ ‏فَأَشْكَلَ ‏ ‏عَلَيْهِ فَلَا يَنْصَرِفْ حَتَّى يَسْمَعَ صَوْتًا أَوْ يَجِدَ رِيحًا ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('eaf5ce78-ff11-5d10-a629-c0f4d36d92b1', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '152', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي رَوْقٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبَّلَهَا وَلَمْ يَتَوَضَّأْ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏كَذَا ‏ ‏رَوَاهُ ‏ ‏الْفِرْيَابِيُّ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَهُوَ مُرْسَلٌ ‏ ‏إِبْرَاهِيمُ التَّيْمِيُّ ‏ ‏لَمْ يَسْمَعْ مِنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏مَاتَ ‏ ‏إِبْرَاهِيمُ التَّيْمِيُّ ‏ ‏وَلَمْ يَبْلُغْ أَرْبَعِينَ سَنَةً وَكَانَ يُكْنَى ‏ ‏أَبَا أَسْمَاءَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2be6aa2b-00b2-5e23-8604-27e323f5d374', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '153', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبَّلَ امْرَأَةً مِنْ نِسَائِهِ ثُمَّ خَرَجَ إِلَى الصَّلَاةِ وَلَمْ يَتَوَضَّأْ ‏ ‏قَالَ ‏ ‏عُرْوَةُ ‏ ‏مَنْ هِيَ إِلَّا أَنْتِ فَضَحِكَتْ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏هَكَذَا ‏ ‏رَوَاهُ ‏ ‏زَائِدَةُ ‏ ‏وَعَبْدُ الْحَمِيدِ الْحِمَّانِيُّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الْأَعْمَشِ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مَخْلَدٍ الطَّالْقَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ يَعْنِي ابْنَ مَغْرَاءَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏أَخْبَرَنَا ‏ ‏أَصْحَابٌ لَنَا ‏ ‏عَنْ ‏ ‏عُرْوَةَ الْمُزَنِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏بِهَذَا الْحَدِيثِ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏قَالَ ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْقَطَّانُ ‏ ‏لِرَجُلٍ ‏ ‏احْكِ عَنِّي أَنَّ هَذَيْنِ ‏ ‏يَعْنِي حَدِيثَ ‏ ‏الْأَعْمَشِ ‏ ‏هَذَا عَنْ ‏ ‏حَبِيبٍ ‏ ‏وَحَدِيثَهُ بِهَذَا الْإِسْنَادِ فِي الْمُسْتَحَاضَةِ أَنَّهَا تَتَوَضَّأُ لِكُلِّ صَلَاةٍ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏احْكِ عَنِّي ‏ ‏أَنَّهُمَا شِبْهُ لَا شَيْءَ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَرُوِيَ عَنْ ‏ ‏الثَّوْرِيِّ ‏ ‏قَالَ ‏ ‏مَا حَدَّثَنَا ‏ ‏حَبِيبٌ ‏ ‏إِلَّا عَنْ ‏ ‏عُرْوَةَ الْمُزَنِيِّ ‏ ‏يَعْنِي لَمْ يُحَدِّثْهُمْ عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏بِشَيْءٍ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَقَدْ ‏ ‏رَوَى ‏ ‏حَمْزَةُ الزَّيَّاتُ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏حَدِيثًا صَحِيحًا ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('923a1daf-414f-5f6b-ad64-55a8615ae553', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '154', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُرْوَةَ ‏ ‏يَقُولُ دَخَلْتُ عَلَى ‏ ‏مَرْوَانَ بْنِ الْحَكَمِ ‏ ‏فَذَكَرْنَا مَا يَكُونُ مِنْهُ الْوُضُوءُ فَقَالَ ‏ ‏مَرْوَانُ ‏ ‏وَمِنْ مَسِّ الذَّكَرِ فَقَالَ ‏ ‏عُرْوَةُ ‏ ‏مَا عَلِمْتُ ذَلِكَ ‏ ‏فَقَالَ ‏ ‏مَرْوَانُ ‏ ‏أَخْبَرَتْنِي ‏ ‏بُسْرَةُ بِنْتُ صَفْوَانَ ‏ ‏أَنَّهَا سَمِعَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ مَسَّ ذَكَرَهُ فَلْيَتَوَضَّأْ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('24fbf583-a099-505f-9a35-d3ad43e90cb8', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '155', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏مُلَازِمُ بْنُ عَمْرٍو الْحَنَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَدْرٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ طَلْقٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَدِمْنَا عَلَى نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ رَجُلٌ كَأَنَّهُ ‏ ‏بَدَوِيٌّ فَقَالَ يَا نَبِيَّ اللَّهِ مَا ‏ ‏تَرَى فِي مَسِّ الرَّجُلِ ذَكَرَهُ بَعْدَ مَا يَتَوَضَّأُ فَقَالَ ‏ ‏هَلْ هُوَ إِلَّا ‏ ‏مُضْغَةٌ ‏ ‏مِنْهُ ‏ ‏أَوْ قَالَ ‏ ‏بَضْعَةٌ ‏ ‏مِنْهُ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏رَوَاهُ ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏وَسُفْيَانُ الثَّوْرِيُّ ‏ ‏وَشُعْبَةُ ‏ ‏وَابْنُ عُيَيْنَةَ ‏ ‏وَجَرِيرٌ الرَّازِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ طَلْقٍ ‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَابِرٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ طَلْقٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏بِإِسْنَادِهِ وَمَعْنَاهُ وَقَالَ فِي الصَّلَاةِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5b873fcb-d004-536b-831c-1eac7311f87b', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '156', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ الرَّازِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْوُضُوءِ مِنْ لُحُومِ الْإِبِلِ فَقَالَ تَوَضَّئُوا مِنْهَا وَسُئِلَ عَنْ لُحُومِ الْغَنَمِ فَقَالَ لَا تَوَضَّئُوا مِنْهَا وَسُئِلَ عَنْ الصَّلَاةِ فِي مَبَارِكِ الْإِبِلِ فَقَالَ لَا تُصَلُّوا فِي مَبَارِكِ الْإِبِلِ فَإِنَّهَا مِنْ الشَّيَاطِينِ وَسُئِلَ عَنْ الصَّلَاةِ فِي ‏ ‏مَرَابِضِ ‏ ‏الْغَنَمِ فَقَالَ صَلُّوا فِيهَا فَإِنَّهَا بَرَكَةٌ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('39814903-9791-5f9a-9104-41ddcd9b5c43', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '157', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏وَأَيُّوبُ بْنُ مُحَمَّدٍ الرَّقِّيُّ ‏ ‏وَعَمْرُو بْنُ عُثْمَانَ الْحِمْصِيُّ ‏ ‏الْمَعْنَى ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُعَاوِيَةَ ‏ ‏أَخْبَرَنَا ‏ ‏هِلَالُ بْنُ مَيْمُونٍ الْجُهَنِيُّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏قَالَ ‏ ‏هِلَالٌ ‏ ‏لَا أَعْلَمُهُ إِلَّا ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏وَقَالَ ‏ ‏أَيُّوبُ ‏ ‏وَعَمْرٌو ‏ ‏أُرَاهُ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِغُلَامٍ وَهُوَ يَسْلُخُ شَاةً فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَنَحَّ حَتَّى أُرِيَكَ فَأَدْخَلَ يَدَهُ بَيْنَ الْجِلْدِ وَاللَّحْمِ ‏ ‏فَدَحَسَ ‏ ‏بِهَا حَتَّى ‏ ‏تَوَارَتْ ‏ ‏إِلَى الْإِبِطِ ثُمَّ مَضَى فَصَلَّى لِلنَّاسِ وَلَمْ يَتَوَضَّأْ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏زَادَ ‏ ‏عَمْرٌو ‏ ‏فِي حَدِيثِهِ ‏ ‏يَعْنِي لَمْ يَمَسَّ مَاءً ‏ ‏وَقَالَ عَنْ ‏ ‏هِلَالِ بْنِ مَيْمُونٍ الرَّمْلِيِّ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَرَوَاهُ ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏هِلَالٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُرْسَلًا لَمْ يَذْكُرْ ‏ ‏أَبَا سَعِيدٍ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
