insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('be849c40-be40-5ed4-9bb3-2145789c421c', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '159', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ كَتِفَ شَاةٍ ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('911401e5-414c-5aa6-94c9-bc86161c4a82', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '160', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏وَمُحَمَّدُ بْنُ سُلَيْمَانَ الْأَنْبَارِيُّ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏عَنْ ‏ ‏أَبِي صَخْرَةَ جَامِعِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏ضِفْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ فَأَمَرَ بِجَنْبٍ فَشُوِيَ وَأَخَذَ ‏ ‏الشَّفْرَةَ ‏ ‏فَجَعَلَ ‏ ‏يَحُزُّ ‏ ‏لِي بِهَا مِنْهُ قَالَ فَجَاءَ ‏ ‏بِلَالٌ ‏ ‏فَآذَنَهُ بِالصَّلَاةِ قَالَ فَأَلْقَى ‏ ‏الشَّفْرَةَ ‏ ‏وَقَالَ مَا لَهُ ‏ ‏تَرِبَتْ يَدَاهُ ‏ ‏وَقَامَ يُصَلِّ ‏ ‏زَادَ ‏ ‏الْأَنْبَارِيُّ ‏ ‏وَكَانَ شَارِبِي ‏ ‏وَفَى ‏ ‏فَقَصَّهُ لِي عَلَى سِوَاكٍ ‏ ‏أَوْ قَالَ أَقُصُّهُ لَكَ عَلَى سِوَاكٍ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('48d0ee77-3450-5bc1-825e-113262b08920', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '161', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَكَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَتِفًا ثُمَّ مَسَحَ يَدَهُ ‏ ‏بِمِسْحٍ ‏ ‏كَانَ تَحْتَهُ ثُمَّ قَامَ فَصَلَّى ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6a6f3449-0d19-5288-ae0f-77f783692c04', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '162', '‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ عُمَرَ النَّمَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ يَعْمَرَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْتَهَشَ مِنْ كَتِفٍ ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9a5c5458-4c47-5430-afcd-2fb63b40f232', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '163', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ الْحَسَنِ الْخَثْعَمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ الْمُنْكَدِرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏قَرَّبْتُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُبْزًا وَلَحْمًا ‏ ‏فَأَكَلَ ثُمَّ دَعَا بِوَضُوءٍ فَتَوَضَّأَ بِهِ ثُمَّ صَلَّى الظُّهْرَ ثُمَّ دَعَا بِفَضْلِ طَعَامِهِ فَأَكَلَ ثُمَّ قَامَ إِلَى الصَّلَاةِ وَلَمْ يَتَوَضَّأْ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a7cc0c50-e949-5b7d-a774-2804c9a741d8', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '164', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ سَهْلٍ أَبُو عِمْرَانَ الرَّمْلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبُ بْنُ أَبِي حَمْزَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كَانَ آخِرَ الْأَمْرَيْنِ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَرْكُ الْوُضُوءِ مِمَّا غَيَّرَتْ النَّارُ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏هَذَا اخْتِصَارٌ مِنْ الْحَدِيثِ الْأَوَّلِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('465a6d53-d312-5053-8325-1108bf1ebcdc', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '165', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَمْرِو بْنِ السَّرْحِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ أَبِي كَرِيمَةَ ‏ ‏قَالَ ‏ ‏ابْنُ السَّرْحِ بْنُ أَبِي كَرِيمَةَ ‏ ‏مِنْ خِيَارِ الْمُسْلِمِينَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُبَيْدُ بْنُ ثُمَامَةَ الْمُرَادِيُّ ‏ ‏قَالَ ‏ ‏قَدِمَ عَلَيْنَا ‏ ‏مِصْرَ ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ بْنِ جَزْءٍ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَمِعْتُهُ يُحَدِّثُ فِي مَسْجِدِ ‏ ‏مِصْرَ ‏ ‏قَالَ لَقَدْ رَأَيْتُنِي سَابِعَ سَبْعَةٍ ‏ ‏أَوْ سَادِسَ سِتَّةٍ ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي دَارِ رَجُلٍ فَمَرَّ ‏ ‏بِلَالٌ ‏ ‏فَنَادَاهُ بِالصَّلَاةِ فَخَرَجْنَا فَمَرَرْنَا بِرَجُلٍ ‏ ‏وَبُرْمَتُهُ ‏ ‏عَلَى النَّارِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَطَابَتْ ‏ ‏بُرْمَتُكَ ‏ ‏قَالَ نَعَمْ بِأَبِي أَنْتَ وَأُمِّي ‏ ‏فَتَنَاوَلَ مِنْهَا ‏ ‏بَضْعَةً ‏ ‏فَلَمْ يَزَلْ يَعْلُكُهَا حَتَّى أَحْرَمَ بِالصَّلَاةِ وَأَنَا أَنْظُرُ إِلَيْهِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('da8896df-7b29-5a50-a4fc-fa12fa215c8c', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '166', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ حَفْصٍ ‏ ‏عَنْ ‏ ‏الْأَغَرِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوُضُوءُ مِمَّا أَنْضَجَتْ النَّارُ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e6db614b-300a-512d-98bb-e255dcc6b7bb', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '167', '‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى يَعْنِي ابْنَ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏أَنَّ ‏ ‏أَبَا سُفْيَانَ بْنَ سَعِيدِ بْنِ الْمُغِيرَةِ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّهُ دَخَلَ عَلَى ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏فَسَقَتْهُ ‏ ‏قَدَحًا ‏ ‏مِنْ ‏ ‏سَوِيقٍ ‏ ‏فَدَعَا بِمَاءٍ فَتَمَضْمَضَ فَقَالَتْ يَا ابْنَ أُخْتِي أَلَا تَوَضَّأُ إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَوَضَّئُوا مِمَّا غَيَّرَتْ النَّارُ ‏ ‏أَوْ قَالَ مِمَّا مَسَّتْ النَّارُ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏فِي حَدِيثِ ‏ ‏الزُّهْرِيِّ ‏ ‏يَا ابْنَ أَخِي ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('009cc425-29b4-585a-b4e4-e062d48d147c', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '168', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَرِبَ لَبَنًا فَدَعَا بِمَاءٍ فَتَمَضْمَضَ ثُمَّ قَالَ إِنَّ لَهُ دَسَمًا ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('44a64f37-05bc-5941-845c-0998e19ba7e3', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '169', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ الْحُبَابِ ‏ ‏عَنْ ‏ ‏مُطِيعِ بْنِ رَاشِدٍ ‏ ‏عَنْ ‏ ‏تَوْبَةَ الْعَنْبَرِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَرِبَ لَبَنًا فَلَمْ يُمَضْمِضْ وَلَمْ يَتَوَضَّأْ وَصَلَّى ‏ ‏قَالَ ‏ ‏زَيْدٌ ‏ ‏دَلَّنِي ‏ ‏شُعْبَةُ ‏ ‏عَلَى هَذَا الشَّيْخِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('41a01750-b745-51c5-b6c1-c66a9098121c', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '170', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو تَوْبَةَ الرَّبِيعُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏حَدَّثَنِي ‏ ‏صَدَقَةُ بْنُ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَقِيلِ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي فِي ‏ ‏غَزْوَةِ ذَاتِ الرِّقَاعِ ‏ ‏فَأَصَابَ رَجُلٌ امْرَأَةَ رَجُلٍ مِنْ الْمُشْرِكِينَ فَحَلَفَ أَنْ لَا أَنْتَهِيَ حَتَّى ‏ ‏أُهَرِيقَ دَمًا فِي ‏ ‏أَصْحَابِ ‏ ‏مُحَمَّدٍ ‏ ‏فَخَرَجَ يَتْبَعُ أَثَرَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَزَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْزِلًا فَقَالَ مَنْ رَجُلٌ ‏ ‏يَكْلَؤُنَا ‏ ‏فَانْتَدَبَ ‏ ‏رَجُلٌ مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَرَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ كُونَا بِفَمِ ‏ ‏الشِّعْبِ ‏ ‏قَالَ فَلَمَّا خَرَجَ الرَّجُلَانِ إِلَى فَمِ ‏ ‏الشِّعْبِ ‏ ‏اضْطَجَعَ ‏ ‏الْمُهَاجِرِيُّ وَقَامَ الْأَنْصَارِيُّ يُصَلِّ وَأَتَى الرَّجُلُ فَلَمَّا رَأَى شَخْصَهُ عَرِفَ أَنَّهُ ‏ ‏رَبِيئَةٌ ‏ ‏لِلْقَوْمِ فَرَمَاهُ بِسَهْمٍ فَوَضَعَهُ فِيهِ فَنَزَعَهُ حَتَّى رَمَاهُ بِثَلَاثَةِ أَسْهُمٍ ثُمَّ رَكَعَ وَسَجَدَ ثُمَّ انْتَبَهَ صَاحِبُهُ فَلَمَّا عَرِفَ أَنَّهُمْ قَدْ نَذِرُوا بِهِ هَرَبَ وَلَمَّا رَأَى ‏ ‏الْمُهَاجِرِيُّ مَا بِالْأَنْصَارِيِّ مِنْ الدَّمِ قَالَ سُبْحَانَ اللَّهِ أَلَا أَنْبَهْتَنِي أَوَّلَ مَا رَمَى قَالَ كُنْتَ فِي سُورَةٍ أَقْرَؤُهَا فَلَمْ أُحِبَّ أَنْ أَقْطَعَهَا ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('99e5b4ec-26bd-5df4-bc76-e8a52beb27eb', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '171', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ مُحَمَّدِ بْنِ حَنْبَلٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شُغِلَ عَنْهَا لَيْلَةً فَأَخَّرَهَا حَتَّى رَقَدْنَا فِي الْمَسْجِدِ ثُمَّ اسْتَيْقَظْنَا ثُمَّ رَقَدْنَا ثُمَّ اسْتَيْقَظْنَا ثُمَّ رَقَدْنَا ثُمَّ خَرَجَ عَلَيْنَا فَقَالَ لَيْسَ أَحَدٌ يَنْتَظِرُ الصَّلَاةَ غَيْرُكُمْ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5bce68e5-85f4-557e-bc88-098c80f90703', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '172', '‏ ‏حَدَّثَنَا ‏ ‏شَاذُّ بْنُ فَيَّاضٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْتَظِرُونَ الْعِشَاءَ الْآخِرَةَ حَتَّى ‏ ‏تَخْفِقَ ‏ ‏رُءُوسُهُمْ ثُمَّ يُصَلُّونَ وَلَا يَتَوَضَّئُونَ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏زَادَ فِيهِ ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نَخْفِقُ ‏ ‏عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَوَاهُ ‏ ‏ابْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏بِلَفْظٍ آخَرَ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9e071aa0-a407-5e83-b394-23052bd74d71', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '173', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَعِيلَ ‏ ‏وَدَاوُدُ بْنُ شَبِيبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏أَنَّ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ صَلَاةُ الْعِشَاءِ فَقَامَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ لِي حَاجَةً ‏ ‏فَقَامَ ‏ ‏يُنَاجِيهِ ‏ ‏حَتَّى نَعَسَ الْقَوْمُ ‏ ‏أَوْ بَعْضُ الْقَوْمِ ‏ ‏ثُمَّ صَلَّى بِهِمْ وَلَمْ يَذْكُرْ وُضُوءًا ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d842aa63-10d7-508a-ab6f-e17656f4c018', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '174', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ مَعِينٍ ‏ ‏وَهَنَّادُ بْنُ السَّرِيِّ ‏ ‏وَعُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ السَّلَامِ بْنِ حَرْبٍ ‏ ‏وَهَذَا لَفْظُ حَدِيثِ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي خَالِدٍ الدَّالَانِيِّ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَسْجُدُ وَيَنَامُ وَيَنْفُخُ ثُمَّ يَقُومُ فَيُصَلِّي وَلَا يَتَوَضَّأُ قَالَ فَقُلْتُ لَهُ صَلَّيْتَ وَلَمْ تَتَوَضَّأْ وَقَدْ نِمْتَ فَقَالَ ‏ ‏إِنَّمَا الْوُضُوءُ عَلَى مَنْ نَامَ مُضْطَجِعًا ‏ ‏زَادَ ‏ ‏عُثْمَانُ ‏ ‏وَهَنَّادٌ ‏ ‏فَإِنَّهُ إِذَا اضْطَجَعَ اسْتَرْخَتْ مَفَاصِلُهُ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏قَوْلُهُ الْوُضُوءُ عَلَى مَنْ نَامَ مُضْطَجِعًا هُوَ ‏ ‏حَدِيثٌ مُنْكَرٌ ‏ ‏لَمْ يَرْوِهِ إِلَّا ‏ ‏يَزِيدُ أَبُو خَالِدٍ الدَّالَانِيُّ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَرَوَى أَوَّلَهُ جَمَاعَةٌ عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَلَمْ يَذْكُرُوا شَيْئًا مِنْ هَذَا وَقَالَ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَحْفُوظًا ‏ ‏وَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَنَامُ عَيْنَايَ وَلَا يَنَامُ قَلْبِي ‏ ‏و قَالَ ‏ ‏شُعْبَةُ ‏ ‏إِنَّمَا سَمِعَ ‏ ‏قَتَادَةُ ‏ ‏مِنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏أَرْبَعَةَ أَحَادِيثَ حَدِيثَ ‏ ‏يُونُسَ بْنِ مَتَّى ‏ ‏وَحَدِيثَ ‏ ‏ابْنِ عُمَرَ ‏ ‏فِي الصَّلَاةِ وَحَدِيثَ الْقُضَاةُ ثَلَاثَةٌ وَحَدِيثَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏حَدَّثَنِي رِجَالٌ مَرْضِيُّونَ مِنْهُمْ ‏ ‏عُمَرُ ‏ ‏وَأَرْضَاهُمْ عِنْدِي ‏ ‏عُمَرُ ‏ ‏قَالَ ‏ ‏أَبُو دَاوُد ‏ ‏وَذَكَرْتُ حَدِيثَ ‏ ‏يَزِيدَ الدَّالَانِيِّ ‏ ‏لِأَحْمَدَ بْنِ حَنْبَلٍ ‏ ‏فَانْتَهَرَنِي ‏ ‏اسْتِعْظَامًا لَهُ وَقَالَ مَا ‏ ‏لِيَزِيدَ الدَّالَانِيِّ ‏ ‏يُدْخِلُ عَلَى أَصْحَابِ ‏ ‏قَتَادَةَ ‏ ‏وَلَمْ يَعْبَأْ بِالْحَدِيثِ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, had