insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('94e0280c-8b07-5395-b2f0-d74bc97faed3', 'cbb6b16b-73c0-414a-bcb6-6f0ab3d9bfe7', '175', '‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ الْحِمْصِيُّ ‏ ‏فِي ‏ ‏آخَرِينَ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏عَنْ ‏ ‏الْوَضِينِ بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏مَحْفُوظِ بْنِ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَائِذٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وِكَاءُ ‏ ‏السَّهِ ‏ ‏الْعَيْنَانِ فَمَنْ نَامَ فَلْيَتَوَضَّأْ ‏', 'سنن أبي داود — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
