insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5a207168-b9af-53b9-bac6-f9ae35b718ee', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '1', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُقْبَلُ صَلَاةٌ بِغَيْرِ طُهُورٍ وَلَا صَدَقَةٌ مِنْ ‏ ‏غُلُولٍ ‏ ‏قَالَ ‏ ‏هَنَّادٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏إِلَّا بِطُهُورٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا الْحَدِيثُ ‏ ‏أَصَحُّ شَيْءٍ فِي هَذَا الْبَابِ وَأَحْسَنُ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏وَأَنَسٍ ‏ ‏وَأَبُو الْمَلِيحِ بْنُ أُسَامَةَ ‏ ‏اسْمُهُ ‏ ‏عَامِرٌ ‏ ‏وَيُقَالُ ‏ ‏زَيْدُ بْنُ أُسَامَةَ بْنِ عُمَيْرٍ الْهُذَلِيُّ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f4ee28d2-b8db-5159-a0ac-01108289d4a9', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '2', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ مُوسَى الْأَنْصَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مَعْنُ بْنُ عِيسَى الْقَزَّازُ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَضَّأَ الْعَبْدُ الْمُسْلِمُ ‏ ‏أَوْ الْمُؤْمِنُ ‏ ‏فَغَسَلَ وَجْهَهُ خَرَجَتْ مِنْ وَجْهِهِ كُلُّ خَطِيئَةٍ نَظَرَ إِلَيْهَا بِعَيْنَيْهِ مَعَ الْمَاءِ ‏ ‏أَوْ مَعَ آخِرِ قَطْرِ الْمَاءِ أَوْ نَحْوَ هَذَا ‏ ‏وَإِذَا غَسَلَ يَدَيْهِ خَرَجَتْ مِنْ يَدَيْهِ كُلُّ خَطِيئَةٍ ‏ ‏بَطَشَتْهَا ‏ ‏يَدَاهُ مَعَ الْمَاءِ ‏ ‏أَوْ مَعَ آخِرِ قَطْرِ الْمَاءِ ‏ ‏حَتَّى يَخْرُجَ نَقِيًّا مِنْ الذُّنُوبِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَهُوَ حَدِيثُ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ أَبِيهِ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَأَبُو صَالِحٍ ‏ ‏وَالِدُ ‏ ‏سُهَيْلٍ ‏ ‏هُوَ ‏ ‏أَبُو صَالِحٍ السَّمَّانُ ‏ ‏وَاسْمُهُ ‏ ‏ذَكْوَانُ ‏ ‏وَأَبُو هُرَيْرَةَ ‏ ‏اخْتُلِفَ فِي اسْمِهِ فَقَالُوا ‏ ‏عَبْدُ شَمْسٍ ‏ ‏وَقَالُوا ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏وَهَكَذَا ‏ ‏قَالَ ‏ ‏مُحَمَّدُ بْنُ إِسْمَعِيلَ ‏ ‏وَهُوَ الْأَصَحُّ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏وَثَوْبَانَ ‏ ‏وَالصُّنَابِحِيِّ ‏ ‏وَعَمْرِو بْنِ عَبَسَةَ ‏ ‏وَسَلْمَانَ ‏ ‏وَعَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏وَالصُّنَابِحِيُّ ‏ ‏الَّذِي رَوَى عَنْ ‏ ‏أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏لَيْسَ لَهُ سَمَاعٌ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاسْمُهُ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عُسَيْلَةَ وَيُكْنَى أَبَا عَبْدِ اللَّهِ ‏ ‏رَحَلَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُبِضَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي الطَّرِيقِ وَقَدْ رَوَى عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَادِيثَ ‏ ‏وَالصُّنَابِحُ بْنُ الْأَعْسَرِ الْأَحْمَسِيُّ ‏ ‏صَاحِبُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَالُ لَهُ ‏ ‏الصُّنَابِحِيُّ ‏ ‏أَيْضًا ‏ ‏وَإِنَّمَا حَدِيثُهُ قَالَ سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنِّي مُكَاثِرٌ بِكُمْ الْأُمَمَ فَلَا تَقْتَتِلُنَّ بَعْدِي ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('03b03280-3c0e-5adb-95a2-98d07dca52a7', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '3', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏وَهَنَّادٌ ‏ ‏وَمَحْمُودُ بْنُ غَيْلَانَ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْحَنَفِيَّةِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مِفْتَاحُ الصَّلَاةِ الطُّهُورُ وَتَحْرِيمُهَا التَّكْبِيرُ وَتَحْلِيلُهَا التَّسْلِيمُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا الْحَدِيثُ ‏ ‏أَصَحُّ شَيْءٍ فِي هَذَا الْبَابِ وَأَحْسَنُ ‏ ‏وَعَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏هُوَ صَدُوقٌ وَقَدْ تَكَلَّمَ فِيهِ بَعْضُ أَهْلِ الْعِلْمِ مِنْ قِبَلِ حِفْظِهِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏و سَمِعْت ‏ ‏مُحَمَّدَ بْنَ إِسْمَعِيلَ ‏ ‏يَقُولُ ‏ ‏كَانَ ‏ ‏أَحْمَدُ بْنُ حَنْبَلٍ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏وَالْحُمَيْدِيُّ ‏ ‏يَحْتَجُّونَ بِحَدِيثِ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏وَهُوَ مُقَارِبُ الْحَدِيثِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏وَأَبِي سَعِيدٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('16c928fd-633c-58cb-98bb-f58ae5b1a983', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '4', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ مُحَمَّدُ بْنُ زَنْجَوَيْهِ الْبَغْدَادِيُّ ‏ ‏وَغَيْرُ وَاحِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ قَرْمٍ ‏ ‏عَنْ ‏ ‏أَبِي يَحْيَى الْقَتَّاتِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِفْتَاحُ الْجَنَّةِ الصَّلَاةُ وَمِفْتَاحُ الصَّلَاةِ الْوُضُوءُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6a0c95fe-08f9-5a4b-a7ff-b91bcf110581', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '5', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏وَهَنَّادٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ الْخَلَاءَ قَالَ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَقَدْ قَالَ مَرَّةً أُخْرَى أَعُوذُ بِكَ ‏ ‏مِنْ ‏ ‏الْخُبْثِ ‏ ‏وَالْخَبِيثِ ‏ ‏أَوْ ‏ ‏الْخُبُثِ ‏ ‏وَالْخَبَائِثِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏وَزَيْدِ بْنِ أَرْقَمَ ‏ ‏وَجَابِرٍ ‏ ‏وَابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏أَنَسٍ ‏ ‏أَصَحُّ شَيْءٍ فِي هَذَا الْبَابِ وَأَحْسَنُ ‏ ‏وَحَدِيثُ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏فِي إِسْنَادِهِ اضْطِرَابٌ ‏ ‏رَوَى ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏وَسَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏فَقَالَ ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ عَوْفٍ الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏و قَالَ ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏وَرَوَاهُ ‏ ‏شُعْبَةُ ‏ ‏وَمَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏فَقَالَ ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏وَقَالَ ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ أَبِيهِ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏سَأَلْتُ ‏ ‏مُحَمَّدًا ‏ ‏عَنْ هَذَا ‏ ‏فَقَالَ ‏ ‏يُحْتَمَلُ أَنْ يَكُونَ ‏ ‏قَتَادَةُ ‏ ‏رَوَى عَنْهُمَا جَمِيعًا ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6352acef-0107-57e2-97d8-ab7f98dc5737', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '6', '‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدَةَ الضَّبِّيُّ الْبَصْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا دَخَلَ الْخَلَاءَ قَالَ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ‏ ‏الْخُبْثِ ‏ ‏وَالْخَبَائِثِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('21cb6e26-041d-5b0b-a5bf-11921bbe3526', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '7', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْمَعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ إِسْمَعِيلَ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ بْنِ يُونُسَ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَرَجَ مِنْ الْخَلَاءِ قَالَ ‏ ‏غُفْرَانَكَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ غَرِيبٌ ‏ ‏لَا نَعْرِفُهُ إِلَّا مِنْ حَدِيثِ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ أَبِي بُرْدَةَ ‏ ‏وَأَبُو بُرْدَةَ بْنُ أَبِي مُوسَى ‏ ‏اسْمُهُ ‏ ‏عَامِرُ بْنُ عَبْدِ اللَّهِ بْنِ قَيْسٍ الْأَشْعَرِيُّ ‏ ‏وَلَا نَعْرِفُ فِي هَذَا الْبَابِ إِلَّا حَدِيثَ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3692ba28-a40a-5b4e-b0b6-aa9808558df4', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '8', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَبْدِ الرَّحْمَنِ الْمَخْزُومِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءَ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَتَيْتُمْ ‏ ‏الْغَائِطَ ‏ ‏فَلَا تَسْتَقْبِلُوا الْقِبْلَةَ ‏ ‏بِغَائِطٍ ‏ ‏وَلَا بَوْلٍ وَلَا تَسْتَدْبِرُوهَا وَلَكِنْ شَرِّقُوا أَوْ غَرِّبُوا ‏ ‏قَالَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏فَقَدِمْنَا ‏ ‏الشَّامَ ‏ ‏فَوَجَدْنَا مَرَاحِيضَ قَدْ بُنِيَتْ مُسْتَقْبَلَ الْقِبْلَةِ فَنَنْحَرِفُ عَنْهَا وَنَسْتَغْفِرُ اللَّهَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ جَزْءٍ الزُّبَيْدِيِّ ‏ ‏وَمَعْقِلِ بْنِ أَبِي الْهَيْثَمِ ‏ ‏وَيُقَالُ ‏ ‏مَعْقِلُ بْنُ أَبِي مَعْقِلٍ ‏ ‏وَأَبِي أُمَامَةَ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏وَسَهْلِ بْنِ حُنَيْفٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏أَبِي أَيُّوبَ ‏ ‏أَحْسَنُ شَيْءٍ فِي هَذَا الْبَابِ وَأَصَحُّ ‏ ‏وَأَبُو أَيُّوبَ ‏ ‏اسْمُهُ ‏ ‏خَالِدُ بْنُ زَيْدٍ ‏ ‏وَالزُّهْرِيُّ ‏ ‏اسْمُهُ ‏ ‏مُحَمَّدُ بْنُ مُسْلِمٍ بْنِ عُبَيْدِ اللَّهِ بْنِ شِهَابٍ الزُّهْرِيُّ ‏ ‏وَكُنْيَتُهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏قَالَ ‏ ‏أَبُو الْوَلِيدِ الْمَكِّيُّ ‏ ‏قَالَ ‏ ‏أَبُو عَبْدِ اللَّهِ مُحَمَّدُ بْنُ إِدْرِيسَ الشَّافِعِيُّ ‏ ‏إِنَّمَا مَعْنَى قَوْلِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَسْتَقْبِلُوا الْقِبْلَةَ ‏ ‏بِغَائِطٍ ‏ ‏وَلَا بِبَوْلٍ وَلَا تَسْتَدْبِرُوهَا إِنَّمَا هَذَا فِي ‏ ‏الْفَيَافِي ‏ ‏وَأَمَّا فِي ‏ ‏الْكُنُفِ ‏ ‏الْمَبْنِيَّةِ لَهُ رُخْصَةٌ فِي أَنْ يَسْتَقْبِلَهَا ‏ ‏وَهَكَذَا ‏ ‏قَالَ ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏و قَالَ ‏ ‏أَحْمَدُ بْنُ حَنْبَلٍ ‏ ‏رَحِمَهُ اللَّهُ ‏ ‏إِنَّمَا الرُّخْصَةُ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏اسْتِدْبَارِ ‏ ‏الْقِبْلَةِ ‏ ‏بِغَائِطٍ ‏ ‏أَوْ بَوْلٍ وَأَمَّا اسْتِقْبَالُ الْقِبْلَةِ فَلَا يَسْتَقْبِلُهَا كَأَنَّهُ لَمْ يَرَ فِي الصَّحْرَاءِ وَلَا فِي ‏ ‏الْكُنُفِ ‏ ‏أَنْ يَسْتَقْبِلَ الْقِبْلَةَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0fe3e08c-3080-55b0-9859-e02e4961e8e6', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '9', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏وَمُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏نَهَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَسْتَقْبِلَ الْقِبْلَةَ بِبَوْلٍ فَرَأَيْتُهُ قَبْلَ أَنْ يُقْبَضَ بِعَامٍ يَسْتَقْبِلُهَا ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏وَعَائِشَةَ ‏ ‏وَعَمَّارِ بْنِ يَاسِرٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏جَابِرٍ ‏ ‏فِي هَذَا الْبَابِ ‏ ‏حَدِيثٌ حَسَنٌ غَرِيبٌ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3b8d54af-42c7-5c01-a38e-4086ea049355', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '10', '‏ ‏وَقَدْ رَوَى هَذَا الْحَدِيثَ ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏أَنَّهُ رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَبُولُ مُسْتَقْبِلَ الْقِبْلَةِ ‏ ‏حَدَّثَنَا ‏ ‏بِذَلِكَ ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏وَحَدِيثُ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَصَحُّ مِنْ حَدِيثِ ‏ ‏ابْنِ لَهِيعَةَ ‏ ‏وَابْنُ لَهِيعَةَ ‏ ‏ضَعِيفٌ عِنْدَ أَهْلِ الْحَدِيثِ ضَعَّفَهُ ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْقَطَّانُ ‏ ‏وَغَيْرُهُ مِنْ قِبَلِ حِفْظِهِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('13e9d52a-f2ac-5fa1-b68d-b3b8de38e06e', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '11', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏وَاسِعِ بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَقِيتُ ‏ ‏يَوْمًا عَلَى بَيْتِ ‏ ‏حَفْصَةَ ‏ ‏فَرَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى حَاجَتِهِ مُسْتَقْبِلَ ‏ ‏الشَّامِ ‏ ‏مُسْتَدْبِرَ ‏ ‏الْكَعْبَةِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('963dc757-7006-5c13-9060-5cf739d813a0', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '12', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حُجْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَنْ حَدَّثَكُمْ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَبُولُ قَائِمًا فَلَا تُصَدِّقُوهُ مَا كَانَ يَبُولُ إِلَّا قَاعِدًا ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏وَبُرَيْدَةَ ‏ ‏وَعَبْدِ الرَّحْمَنِ بْنِ حَسَنَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏عَائِشَةَ ‏ ‏أَحْسَنُ شَيْءٍ فِي هَذَا الْبَابِ وَأَصَحُّ ‏ ‏وَحَدِيثُ ‏ ‏عُمَرَ ‏ ‏إِنَّمَا ‏ ‏رُوِيَ مِنْ حَدِيثِ ‏ ‏عَبْدِ الْكَرِيمِ بْنِ أَبِي الْمُخَارِقِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏قَالَ ‏ ‏رَآنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا أَبُولُ قَائِمًا فَقَالَ يَا ‏ ‏عُمَرُ ‏ ‏لَا تَبُلْ قَائِمًا فَمَا بُلْتُ قَائِمًا بَعْدُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَإِنَّمَا رَفَعَ هَذَا الْحَدِيثَ ‏ ‏عَبْدُ الْكَرِيمِ بْنُ أَبِي الْمُخَارِقِ ‏ ‏وَهُوَ ضَعِيفٌ عِنْدَ أَهْلِ الْحَدِيثِ ضَعَّفَهُ ‏ ‏أَيُّوبُ السَّخْتِيَانِيُّ ‏ ‏وَتَكَلَّمَ فِيهِ ‏ ‏وَرَوَى ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ قَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مَا بُلْتُ قَائِمًا مُنْذُ أَسْلَمْتُ ‏ ‏وَهَذَا ‏ ‏أَصَحُّ مِنْ حَدِيثِ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏وَحَدِيثُ ‏ ‏بُرَيْدَةَ ‏ ‏فِي هَذَا غَيْرُ مَحْفُوظٍ وَمَعْنَى النَّهْيِ عَنْ الْبَوْلِ قَائِمًا عَلَى التَّأْدِيبِ لَا عَلَى التَّحْرِيمِ ‏ ‏وَقَدْ رُوِيَ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏إِنَّ مِنْ ‏ ‏الْجَفَاءِ ‏ ‏أَنْ تَبُولَ وَأَنْتَ قَائِمٌ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('81c6fe49-5a77-5614-b446-800b356263e1', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '13', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى ‏ ‏سُبَاطَةَ ‏ ‏قَوْمٍ فَبَالَ عَلَيْهَا قَائِمًا فَأَتَيْتُهُ ‏ ‏بِوَضُوءٍ ‏ ‏فَذَهَبْتُ لِأَتَأَخَّرَ عَنْهُ فَدَعَانِي حَتَّى كُنْتُ عِنْدَ ‏ ‏عَقِبَيْهِ ‏ ‏فَتَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏و سَمِعْت ‏ ‏الْجَارُودَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏وَكِيعًا ‏ ‏يُحَدِّثُ ‏ ‏بِهَذَا الْحَدِيثِ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏ثُمَّ قَالَ ‏ ‏وَكِيعٌ ‏ ‏هَذَا أَصَحُّ حَدِيثٍ رُوِيَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْحِ ‏ ‏و سَمِعْت ‏ ‏أَبَا عَمَّارٍ الْحُسَيْنَ بْنَ حُرَيْثٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏وَكِيعًا ‏ ‏فَذَكَرَ ‏ ‏نَحْوَهُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَهَكَذَا ‏ ‏رَوَى ‏ ‏مَنْصُورٌ ‏ ‏وَعُبَيْدَةُ الضَّبِّيُّ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏مِثْلَ رِوَايَةِ ‏ ‏الْأَعْمَشِ ‏ ‏وَرَوَى ‏ ‏حَمَّادُ بْنُ أَبِي سُلَيْمَانَ ‏ ‏وَعَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَحَدِيثُ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏أَصَحُّ ‏ ‏وَقَدْ رَخَّصَ قَوْمٌ مِنْ أَهْلِ الْعِلْمِ فِي الْبَوْلِ قَائِمًا ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَعَبِيدَةُ بْنُ عَمْرٍو السَّلْمَانِيُّ ‏ ‏رَوَى عَنْهُ ‏ ‏إِبْرَاهِيمُ النَّخَعِيُّ ‏ ‏وَعَبِيدَةُ ‏ ‏مِنْ كِبَارِ التَّابِعِينَ ‏ ‏يُرْوَى عَنْ ‏ ‏عَبِيدَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَسْلَمْتُ قَبْلَ وَفَاةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِسَنَتَيْنِ ‏ ‏وَعُبَيْدَةُ الضَّبِّيُّ ‏ ‏صَاحِبُ ‏ ‏إِبْرَاهِيمَ ‏ ‏هُوَ ‏ ‏عُبَيْدَةُ بْنُ مُعَتِّبٍ الضَّبِّيُّ وَيُكْنَى أَبَا عَبْدِ الْكَرِيمِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('67bcdc08-b23e-57a0-8e8d-01e13641749b', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '14', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ السَّلَامِ بْنُ حَرْبٍ الْمُلَائِيُّ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ الْحَاجَةَ لَمْ يَرْفَعْ ثَوْبَهُ حَتَّى يَدْنُوَ مِنْ الْأَرْضِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَكَذَا ‏ ‏رَوَى ‏ ‏مُحَمَّدُ بْنُ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏وَرَوَى ‏ ‏وَكِيعٌ ‏ ‏وَأَبُو يَحْيَى الْحِمَّانِيُّ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ الْحَاجَةَ لَمْ يَرْفَعْ ثَوْبَهُ حَتَّى يَدْنُوَ مِنْ الْأَرْضِ ‏ ‏وَكِلَا الْحَدِيثَيْنِ مُرْسَلٌ ‏ ‏وَيُقَالُ لَمْ يَسْمَعْ ‏ ‏الْأَعْمَشُ ‏ ‏مِنْ ‏ ‏أَنَسٍ ‏ ‏وَلَا مِنْ أَحَدٍ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ نَظَرَ إِلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُهُ ‏ ‏يُصَلِّي فَذَكَرَ عَنْهُ حِكَايَةً فِي الصَّلَاةِ ‏ ‏وَالْأَعْمَشُ ‏ ‏اسْمُهُ ‏ ‏سُلَيْمَانُ بْنُ مِهْرَانَ أَبُو مُحَمَّدٍ الْكَاهِلِيُّ ‏ ‏وَهُوَ مَوْلًى لَهُمْ ‏ ‏قَالَ ‏ ‏الْأَعْمَشُ ‏ ‏كَانَ أَبِي حَمِيلًا فَوَرَّثَهُ ‏ ‏مَسْرُوقٌ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3b422bf5-1a75-5318-93f1-7fe7a6f8a104', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '15', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عُمَرَ الْمَكِّيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يَمَسَّ الرَّجُلُ ذَكَرَهُ بِيَمِينِهِ ‏ ‏وَفِي هَذَا ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَسَلْمَانَ ‏ ‏وَأبِي هُرَيْرَةَ ‏ ‏وَسَهْلِ بْنِ حُنَيْفٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَأَبُو قَتَادَةَ الْأَنْصَارِيُّ ‏ ‏اسْمُهُ ‏ ‏الْحَارِثُ بْنُ رِبْعِيٍّ ‏ ‏وَالْعَمَلُ عَلَى هَذَا عِنْدَ عَامَّةِ أَهْلِ الْعِلْمِ كَرِهُوا ‏ ‏الِاسْتِنْجَاءَ ‏ ‏بِالْيَمِينِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('050e69c6-4381-5a61-bfc6-376d50d3e01b', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '16', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏قَالَ قِيلَ ‏ ‏لِسَلْمَانَ ‏ ‏قَدْ عَلَّمَكُمْ نَبِيُّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلَّ شَيْءٍ حَتَّى الْخِرَاءَةَ فَقَالَ ‏ ‏سَلْمَانُ ‏ ‏أَجَلْ ‏ ‏نَهَانَا أَنْ نَسْتَقْبِلَ الْقِبْلَةَ ‏ ‏بِغَائِطٍ ‏ ‏أَوْ بَوْلٍ وَأَنْ ‏ ‏نَسْتَنْجِيَ ‏ ‏بِالْيَمِينِ أَوْ أَنْ ‏ ‏يَسْتَنْجِيَ ‏ ‏أَحَدُنَا بِأَقَلَّ مِنْ ثَلَاثَةِ أَحْجَارٍ أَوْ أَنْ ‏ ‏نَسْتَنْجِيَ ‏ ‏بِرَجِيعٍ ‏ ‏أَوْ بِعَظْمٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَخُزَيْمَةَ بْنِ ثَابِتٍ ‏ ‏وَجَابِرٍ ‏ ‏وَخَلَّادِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَحَدِيثُ ‏ ‏سَلْمَانَ ‏ ‏فِي هَذَا الْبَابِ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَهُوَ قَوْلُ أَكْثَرِ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَنْ بَعْدَهُمْ رَأَوْا أَنَّ ‏ ‏الِاسْتِنْجَاءَ ‏ ‏بِالْحِجَارَةِ يُجْزِئُ وَإِنْ لَمْ ‏ ‏يَسْتَنْجِ ‏ ‏بِالْمَاءِ إِذَا أَنْقَى أَثَرَ ‏ ‏الْغَائِطِ ‏ ‏وَالْبَوْلِ وَبِهِ يَقُولُ ‏ ‏الثَّوْرِيُّ ‏ ‏وَابْنُ الْمُبَارَكِ ‏ ‏وَالشَّافِعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2c0d2b6a-950f-5c5e-8c64-4f465ef35d4f', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '17', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏وَقُتَيْبَةُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏خَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحَاجَتِهِ فَقَالَ ‏ ‏الْتَمِسْ ‏ ‏لِي ثَلَاثَةَ أَحْجَارٍ قَالَ فَأَتَيْتُهُ بِحَجَرَيْنِ وَرَوْثَةٍ فَأَخَذَ الْحَجَرَيْنِ وَأَلْقَى ‏ ‏الرَّوْثَةَ ‏ ‏وَقَالَ إِنَّهَا ‏ ‏رِكْسٌ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَهَكَذَا ‏ ‏رَوَى ‏ ‏قَيْسُ بْنُ الرَّبِيعِ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏نَحْوَ حَدِيثِ ‏ ‏إِسْرَائِيلَ ‏ ‏وَرَوَى ‏ ‏مَعْمَرٌ ‏ ‏وَعَمَّارُ بْنُ رُزَيْقٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَرَوَى ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَرَوَى ‏ ‏زَكَرِيَّا بْنُ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَهَذَا حَدِيثٌ ‏ ‏فِيهِ اضْطِرَابٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ الْعَبْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَأَلْتُ ‏ ‏أَبَا عُبَيْدَةَ بْنَ عَبْدِ اللَّهِ ‏ ‏هَلْ تَذْكُرُ مِنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏شَيْئًا قَالَ لَا ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏سَأَلْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏أَيُّ الرِّوَايَاتِ فِي هَذَا الْحَدِيثِ عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏أَصَحُّ فَلَمْ يَقْضِ فِيهِ بِشَيْءٍ ‏ ‏وَسَأَلْتُ ‏ ‏مُحَمَّدًا ‏ ‏عَنْ هَذَا فَلَمْ يَقْضِ فِيهِ بِشَيْءٍ ‏ ‏وَكَأَنَّهُ رَأَى حَدِيثَ ‏ ‏زُهَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ أَبِيهِ عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَشْبَهَ وَوَضَعَهُ فِي ‏ ‏كِتَابِ الْجَامِعِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَأَصَحُّ شَيْءٍ فِي هَذَا عِنْدِي حَدِيثُ ‏ ‏إِسْرَائِيلَ ‏ ‏وَقَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏لِأَنَّ ‏ ‏إِسْرَائِيلَ ‏ ‏أَثْبَتُ وَأَحْفَظُ لِحَدِيثِ ‏ ‏أَبِي إِسْحَقَ ‏ ‏مِنْ هَؤُلَاءِ ‏ ‏وَتَابَعَهُ عَلَى ذَلِكَ ‏ ‏قَيْسُ بْنُ الرَّبِيعِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏و سَمِعْت ‏ ‏أَبَا مُوسَى مُحَمَّدَ بْنَ الْمُثَنَّى ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ مَهْدِيٍّ ‏ ‏يَقُولُ مَا فَاتَنِي الَّذِي فَاتَنِي مِنْ حَدِيثِ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏إِلَّا لِمَا اتَّكَلْتُ بِهِ عَلَى ‏ ‏إِسْرَائِيلَ ‏ ‏لِأَنَّهُ كَانَ يَأْتِي بِهِ أَتَمَّ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَزُهَيْرٌ ‏ ‏فِي ‏ ‏أَبِي إِسْحَقَ ‏ ‏لَيْسَ بِذَاكَ لِأَنَّ سَمَاعَهُ مِنْهُ بِآخِرَةٍ ‏ ‏قَالَ ‏ ‏و سَمِعْت ‏ ‏أَحْمَدَ بْنَ الْحَسَنِ التِّرْمِذِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَحْمَدَ بْنَ حَنْبَلٍ ‏ ‏يَقُولُ إِذَا سَمِعْتَ الْحَدِيثَ عَنْ ‏ ‏زَائِدَةَ ‏ ‏وَزُهَيْرٍ ‏ ‏فَلَا ‏ ‏تُبَالِي أَنْ لَا تَسْمَعَهُ مِنْ غَيْرِهِمَا إِلَّا حَدِيثَ ‏ ‏أَبِي إِسْحَقَ ‏ ‏وَأَبُو إِسْحَقَ ‏ ‏اسْمُهُ ‏ ‏عَمْرُو بْنُ عَبْدِ اللَّهِ السَّبِيعِيُّ الْهَمْدَانِيُّ ‏ ‏وَأَبُو عُبَيْدَةَ بْنُ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏لَمْ يَسْمَعْ مِنْ أَبِيهِ وَلَا يُعْرَفُ اسْمُهُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3a436daa-7c77-5c25-bc1f-8ecf9811faf7', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '18', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تَسْتَنْجُوا ‏ ‏بِالرَّوْثِ ‏ ‏وَلَا بِالْعِظَامِ فَإِنَّهُ ‏ ‏زَادُ ‏ ‏إِخْوَانِكُمْ مِنْ الْجِنِّ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَسَلْمَانَ ‏ ‏وَجَابِرٍ ‏ ‏وَابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَقَدْ ‏ ‏رَوَى هَذَا الْحَدِيثَ ‏ ‏إِسْمَعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏وَغَيْرُهُ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّهُ كَانَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةَ الْجِنِّ الْحَدِيثَ بِطُولِهِ فَقَالَ ‏ ‏الشَّعْبِيُّ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَا ‏ ‏تَسْتَنْجُوا ‏ ‏بِالرَّوْثِ ‏ ‏وَلَا بِالْعِظَامِ فَإِنَّهُ ‏ ‏زَادُ ‏ ‏إِخْوَانِكُمْ مِنْ الْجِنِّ ‏ ‏وَكَأَنَّ رِوَايَةَ ‏ ‏إِسْمَعِيلَ ‏ ‏أَصَحُّ مِنْ رِوَايَةِ ‏ ‏حَفْصِ بْنِ غِيَاثٍ ‏ ‏وَالْعَمَلُ عَلَى هَذَا الْحَدِيثِ عِنْدَ أَهْلِ الْعِلْمِ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏وَابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1cb6f8dc-e261-5272-aa73-5fd0c73863b5', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '19', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏وَمُحَمَّدُ بْنُ عَبْدِ الْمَلِكِ بْنِ أَبِي الشَّوَارِبِ الْبَصْرِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مُرْنَ أَزْوَاجَكُنَّ أَنْ ‏ ‏يَسْتَطِيبُوا ‏ ‏بِالْمَاءِ فَإِنِّي ‏ ‏أَسْتَحْيِيهِمْ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُهُ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ الْبَجَلِيِّ ‏ ‏وَأَنَسٍ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَعَلَيْهِ الْعَمَلُ عِنْدَ أَهْلِ الْعِلْمِ يَخْتَارُونَ ‏ ‏الِاسْتِنْجَاءَ ‏ ‏بِالْمَاءِ وَإِنْ كَانَ ‏ ‏الِاسْتِنْجَاءُ ‏ ‏بِالْحِجَارَةِ يُجْزِئُ عِنْدَهُمْ فَإِنَّهُمْ اسْتَحَبُّوا ‏ ‏الِاسْتِنْجَاءَ ‏ ‏بِالْمَاءِ وَرَأَوْهُ أَفْضَلَ ‏ ‏وَبِهِ يَقُولُ ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏وَابْنُ الْمُبَارَكِ ‏ ‏وَالشَّافِعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9fdb04de-be2b-5356-ad98-1099df88036a', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '20', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ ‏ ‏فَأَتَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَاجَتَهُ فَأَبْعَدَ فِي الْمَذْهَبِ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي قُرَادٍ ‏ ‏وَأَبِي قَتَادَةَ ‏ ‏وَجَابِرٍ ‏ ‏وَيَحْيَى بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَأَبِي مُوسَى ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏وَبِلَالِ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَيُرْوَى ‏ ‏عَنْ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَرْتَادُ ‏ ‏لِبَوْلِهِ مَكَانًا كَمَا ‏ ‏يَرْتَادُ ‏ ‏مَنْزِلًا ‏ ‏وَأَبُو سَلَمَةَ ‏ ‏اسْمُهُ ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ الزُّهْرِيُّ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a354bd25-caea-5b1d-b7b7-c3f930855a07', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '21', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حُجْرٍ ‏ ‏وَأَحْمَدُ بْنُ مُحَمَّدِ بْنِ مُوسَى مَرْدَوَيْهِ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏أَشْعَثَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يَبُولَ الرَّجُلُ فِي مُسْتَحَمِّهِ وَقَالَ إِنَّ عَامَّةَ الْوَسْوَاسِ مِنْهُ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ غَرِيبٌ ‏ ‏لَا نَعْرِفُهُ مَرْفُوعًا إِلَّا مِنْ حَدِيثِ ‏ ‏أَشْعَثَ بْنِ عَبْدِ اللَّهِ ‏ ‏وَيُقَالُ لَهُ ‏ ‏أَشْعَثُ الْأَعْمَى ‏ ‏وَقَدْ كَرِهَ قَوْمٌ مِنْ أَهْلِ الْعِلْمِ الْبَوْلَ فِي الْمُغْتَسَلِ وَقَالُوا عَامَّةُ الْوَسْوَاسِ مِنْهُ وَرَخَّصَ فِيهِ بَعْضُ أَهْلِ الْعِلْمِ ‏ ‏مِنْهُمْ ‏ ‏ابْنُ سِيرِينَ ‏ ‏وَقِيلَ لَهُ إِنَّهُ يُقَالُ إِنَّ عَامَّةَ الْوَسْوَاسِ مِنْهُ فَقَالَ رَبُّنَا اللَّهُ لَا شَرِيكَ لَهُ ‏ ‏و قَالَ ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏قَدْ وُسِّعَ فِي الْبَوْلِ فِي الْمُغْتَسَلِ إِذَا جَرَى فِيهِ الْمَاءُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏بِذَلِكَ ‏ ‏أَحْمَدُ بْنُ عَبْدَةَ الْآمُلِيُّ ‏ ‏عَنْ ‏ ‏حِبَّانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْمُبَارَكِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9096e39e-e278-5be0-8d5b-5e92b19b6588', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '22', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَقَدْ ‏ ‏رَوَى هَذَا الْحَدِيثَ ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَحَدِيثُ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَزَيْدِ بْنِ خَالِدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كِلَاهُمَا عِنْدِي صَحِيحٌ لِأَنَّهُ قَدْ رُوِيَ مِنْ غَيْرِ وَجْهٍ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا الْحَدِيثُ وَحَدِيثُ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏إِنَّمَا صَحَّ لِأَنَّهُ قَدْ رُوِيَ مِنْ غَيْرِ وَجْهٍ ‏ ‏وَأَمَّا ‏ ‏مُحَمَّدُ بْنُ إِسْمَعِيلَ ‏ ‏فَزَعَمَ أَنَّ حَدِيثَ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ ‏ ‏أَصَحُّ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏وَعَلِيٍّ ‏ ‏وَعَائِشَةَ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏وَحُذَيْفَةَ ‏ ‏وَزَيْدِ بْنِ خَالِدٍ ‏ ‏وَأَنَسٍ ‏ ‏وَعَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏وَابْنِ عُمَرَ ‏ ‏وَأُمِّ حَبِيبَةَ ‏ ‏وَأَبِي أُمَامَةَ ‏ ‏وَأَبِي أَيُّوبَ ‏ ‏وَتَمَّامِ بْنِ عَبَّاسٍ ‏ ‏وَعَبْدِ اللَّهِ بْنِ حَنْظَلَةَ ‏ ‏وَأُمِّ سَلَمَةَ ‏ ‏وَوَاثِلَةَ بْنِ الْأَسْقَعِ ‏ ‏وَأَبِي مُوسَى ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('96a556a0-4d88-51f6-84ff-dc1b1d13ede3', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '23', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ وَلَأَخَّرْتُ صَلَاةَ الْعِشَاءِ إِلَى ثُلُثِ اللَّيْلِ ‏ ‏قَالَ ‏ ‏فَكَانَ ‏ ‏زَيْدُ بْنُ خَالِدٍ ‏ ‏يَشْهَدُ الصَّلَوَاتِ فِي الْمَسْجِدِ وَسِوَاكُهُ عَلَى أُذُنِهِ مَوْضِعَ الْقَلَمِ مِنْ أُذُنِ الْكَاتِبِ لَا يَقُومُ إِلَى الصَّلَاةِ إِلَّا ‏ ‏أُسْتَنَّ ‏ ‏ثُمَّ رَدَّهُ إِلَى مَوْضِعِهِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('adb60bc0-6009-5a9d-be0b-03342ff96b9c', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '24', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ أَحْمَدُ بْنُ بَكَّارٍ الدِّمَشْقِيُّ ‏ ‏يُقَالُ هُوَ مِنْ وَلَدِ ‏ ‏بُسْرِ بْنِ أَرْطَاةَ ‏ ‏صَاحِبِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيِّبِ ‏ ‏وَأَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ اللَّيْلِ فَلَا يُدْخِلْ يَدَهُ فِي الْإِنَاءِ حَتَّى ‏ ‏يُفْرِغَ ‏ ‏عَلَيْهَا مَرَّتَيْنِ أَوْ ثَلَاثًا فَإِنَّهُ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَجَابِرٍ ‏ ‏وَعَائِشَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَهَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏قَالَ ‏ ‏الشَّافِعِيُّ ‏ ‏وَأُحِبُّ لِكُلِّ مَنْ اسْتَيْقَظَ مِنْ النَّوْمِ ‏ ‏قَائِلَةً ‏ ‏كَانَتْ أَوْ غَيْرَهَا أَنْ لَا يُدْخِلَ يَدَهُ فِي وَضُوئِهِ حَتَّى يَغْسِلَهَا فَإِنْ أَدْخَلَ يَدَهُ قَبْلَ أَنْ يَغْسِلَهَا كَرِهْتُ ذَلِكَ لَهُ وَلَمْ يُفْسِدْ ذَلِكَ الْمَاءَ إِذَا لَمْ يَكُنْ عَلَى يَدِهِ نَجَاسَةٌ ‏ ‏و قَالَ ‏ ‏أَحْمَدُ بْنُ حَنْبَلٍ ‏ ‏إِذَا اسْتَيْقَظَ مِنْ النَّوْمِ مِنْ اللَّيْلِ فَأَدْخَلَ يَدَهُ فِي وَضُوئِهِ قَبْلَ أَنْ يَغْسِلَهَا فَأَعْجَبُ إِلَيَّ أَنْ ‏ ‏يُهْرِيقَ ‏ ‏الْمَاءَ ‏ ‏و قَالَ ‏ ‏إِسْحَقُ ‏ ‏إِذَا اسْتَيْقَظَ مِنْ النَّوْمِ بِاللَّيْلِ أَوْ بِالنَّهَارِ فَلَا يُدْخِلْ يَدَهُ فِي وَضُوئِهِ حَتَّى يَغْسِلَهَا ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d950ed91-5dde-5410-997e-7178b71c02f0', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '25', '‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ عَلِيٍّ الْجَهْضَمِيُّ ‏ ‏وَبِشْرُ بْنُ مُعَاذٍ الْعَقَدِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي ثِفَالٍ الْمُرِّيِّ ‏ ‏عَنْ ‏ ‏رَبَاحِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي سُفْيَانَ بْنِ حُوَيْطِبٍ ‏ ‏عَنْ ‏ ‏جَدَّتِهِ ‏ ‏عَنْ ‏ ‏أَبِيهَا ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا وُضُوءَ لِمَنْ لَمْ يَذْكُرْ اسْمَ اللَّهِ عَلَيْهِ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَأَبِي سَعِيدٍ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏وَسَهْلِ بْنِ سَعْدٍ ‏ ‏وَأَنَسٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏قَالَ ‏ ‏أَحْمَدُ بْنُ حَنْبَلٍ ‏ ‏لَا أَعْلَمُ فِي هَذَا الْبَابِ حَدِيثًا لَهُ إِسْنَادٌ جَيِّدٌ ‏ ‏و قَالَ ‏ ‏إِسْحَقُ ‏ ‏إِنْ تَرَكَ التَّسْمِيَةَ عَامِدًا أَعَادَ الْوُضُوءَ وَإِنْ كَانَ نَاسِيًا أَوْ ‏ ‏مُتَأَوِّلًا ‏ ‏أَجْزَأَهُ ‏ ‏قَالَ ‏ ‏مُحَمَّدُ بْنُ إِسْمَعِيلَ ‏ ‏أَحْسَنُ شَيْءٍ فِي هَذَا الْبَابِ حَدِيثُ ‏ ‏رَبَاحِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَرَبَاحُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ جَدَّتِهِ عَنْ أَبِيهَا ‏ ‏وَأَبُوهَا ‏ ‏سَعِيدُ بْنُ زَيْدِ بْنِ عَمْرِو بْنِ نُفَيْلٍ ‏ ‏وَأَبُو ثِفَالٍ الْمُرِّيُّ ‏ ‏اسْمُهُ ‏ ‏ثُمَامَةُ بْنُ حُصَيْنٍ ‏ ‏وَرَبَاحُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏هُوَ ‏ ‏أَبُو بَكْرِ بْنُ حُوَيْطِبٍ ‏ ‏مِنْهُمْ مَنْ رَوَى هَذَا الْحَدِيثَ فَقَالَ عَنْ ‏ ‏أَبِي بَكْرِ بْنِ حُوَيْطِبٍ ‏ ‏فَنَسَبَهُ إِلَى جَدِّهِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عَلِيٍّ الْحُلْوَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عِيَاضٍ ‏ ‏عَنْ ‏ ‏أَبِي ثِفَالٍ الْمُرِّيِّ ‏ ‏عَنْ ‏ ‏رَبَاحِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي سُفْيَانَ بْنِ حُوَيْطِبٍ ‏ ‏عَنْ ‏ ‏جَدَّتِهِ ‏ ‏بِنْتِ سَعِيدِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهَا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d68a1440-f3a5-51ad-91d4-60b7c7b4bee9', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '26', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏وَجَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَضَّأْتَ ‏ ‏فَانْتَثِرْ ‏ ‏وَإِذَا ‏ ‏اسْتَجْمَرْتَ ‏ ‏فَأَوْتِرْ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏وَلَقِيطِ بْنِ صَبِرَةَ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏وَالْمِقْدَامِ بْنِ مَعْدِي كَرِبَ ‏ ‏وَوَائِلِ بْنِ حُجْرٍ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏سَلَمَةَ بْنِ قَيْسٍ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَاخْتَلَفَ أَهْلُ الْعِلْمِ فِيمَنْ تَرَكَ الْمَضْمَضَةَ ‏ ‏وَالِاسْتِنْشَاقَ فَقَالَتْ طَائِفَةٌ مِنْهُمْ إِذَا تَرَكَهُمَا فِي الْوُضُوءِ حَتَّى صَلَّى أَعَادَ الصَّلَاةَ وَرَأَوْا ذَلِكَ فِي الْوُضُوءِ وَالْجَنَابَةِ سَوَاءً ‏ ‏وَبِهِ يَقُولُ ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏وَعَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏و قَالَ ‏ ‏أَحْمَدُ ‏ ‏الِاسْتِنْشَاقُ أَوْكَدُ مِنْ الْمَضْمَضَةِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَقَالَتْ طَائِفَةٌ مِنْ أَهْلِ الْعِلْمِ يُعِيدُ فِي الْجَنَابَةِ وَلَا يُعِيدُ فِي الْوُضُوءِ وَهُوَ قَوْلُ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏وَبَعْضِ أَهْلِ ‏ ‏الْكُوفَةِ ‏ ‏وَقَالَتْ طَائِفَةٌ لَا يُعِيدُ فِي الْوُضُوءِ وَلَا فِي الْجَنَابَةِ لِأَنَّهُمَا سُنَّةٌ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَا تَجِبُ الْإِعَادَةُ عَلَى مَنْ تَرَكَهُمَا فِي الْوُضُوءِ وَلَا فِي الْجَنَابَةِ ‏ ‏وَهُوَ قَوْلُ ‏ ‏مَالِكٍ ‏ ‏وَالشَّافِعِيِّ ‏ ‏فِي آخِرَةٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
