insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0f38b94e-1dad-5561-9076-bdeb9878bab7', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '28', '‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ بْنِ أَبِي الْمُخَارِقِ أَبِي أُمَيَّةَ ‏ ‏عَنْ ‏ ‏حَسَّانَ بْنِ بِلَالٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عَمَّارَ بْنَ يَاسِرٍ ‏ ‏تَوَضَّأَ ‏ ‏فَخَلَّلَ ‏ ‏لِحْيَتَهُ فَقِيلَ لَهُ ‏ ‏أَوْ قَالَ فَقُلْتُ لَهُ ‏ ‏أَتُخَلِّلُ ‏ ‏لِحْيَتَكَ قَالَ وَمَا يَمْنَعُنِي وَلَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُخَلِّلُ ‏ ‏لِحْيَتَهُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏حَسَّانَ بْنِ بِلَالٍ ‏ ‏عَنْ ‏ ‏عَمَّارٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏وَعَائِشَةَ ‏ ‏وَأُمِّ سَلَمَةَ ‏ ‏وَأَنَسٍ ‏ ‏وَابْنِ أَبِي أَوْفَى ‏ ‏وَأَبِي أَيُّوبَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏و سَمِعْت ‏ ‏إِسْحَقَ بْنَ مَنْصُورٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَحْمَدَ بْنَ حَنْبَلٍ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏لَمْ يَسْمَعْ ‏ ‏عَبْدُ الْكَرِيمِ ‏ ‏مِنْ ‏ ‏حَسَّانَ بْنِ بِلَالٍ ‏ ‏حَدِيثَ ‏ ‏التَّخْلِيلِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7afcc1dd-2ad8-5628-82e2-36ab5bcb9cd1', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '29', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُخَلِّلُ ‏ ‏لِحْيَتَهُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏و قَالَ ‏ ‏مُحَمَّدُ بْنُ إِسْمَعِيلَ ‏ ‏أَصَحُّ شَيْءٍ فِي هَذَا الْبَابِ حَدِيثُ ‏ ‏عَامِرِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏و قَالَ ‏ ‏بِهَذَا أَكْثَرُ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَنْ بَعْدَهُمْ رَأَوْا ‏ ‏تَخْلِيلَ ‏ ‏اللِّحْيَةِ ‏ ‏وَبِهِ يَقُولُ ‏ ‏الشَّافِعِيُّ ‏ ‏و قَالَ ‏ ‏أَحْمَدُ ‏ ‏إِنْ سَهَا عَنْ ‏ ‏تَخْلِيلِ ‏ ‏اللِّحْيَةِ فَهُوَ جَائِزٌ ‏ ‏و قَالَ ‏ ‏إِسْحَقُ ‏ ‏إِنْ تَرَكَهُ نَاسِيًا أَوْ ‏ ‏مُتَأَوِّلًا ‏ ‏أَجْزَأَهُ وَإِنْ تَرَكَهُ عَامِدًا أَعَادَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5a75514c-1c84-544a-b03a-5b3d396773f0', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '30', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ مُوسَى الْأَنْصَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مَعْنُ بْنُ عِيسَى الْقَزَّازُ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسَحَ رَأْسَهُ بِيَدَيْهِ فَأَقْبَلَ بِهِمَا وَأَدْبَرَ بَدَأَ بِمُقَدَّمِ رَأْسِهِ ثُمَّ ذَهَبَ بِهِمَا إِلَى قَفَاهُ ثُمَّ رَدَّهُمَا حَتَّى رَجَعَ إِلَى الْمَكَانِ الَّذِي بَدَأَ مِنْهُ ثُمَّ غَسَلَ رِجْلَيْهِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏وَالْمِقْدَامِ بْنِ مَعْدِي كَرِبَ ‏ ‏وَعَائِشَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏أَصَحُّ شَيْءٍ فِي هَذَا الْبَابِ وَأَحْسَنُ ‏ ‏وَبِهِ يَقُولُ ‏ ‏الشَّافِعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('df7dedd7-a425-5c4e-bb6c-d57b8c6d1149', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '31', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذِ ابْنِ عَفْرَاءَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسَحَ بِرَأْسِهِ مَرَّتَيْنِ بَدَأَ بِمُؤَخَّرِ رَأْسِهِ ثُمَّ بِمُقَدَّمِهِ وَبِأُذُنَيْهِ كِلْتَيْهِمَا ظُهُورِهِمَا وَبُطُونِهِمَا ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ ‏ ‏وَحَدِيثُ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏أَصَحُّ مِنْ هَذَا وَأَجْوَدُ إِسْنَادًا ‏ ‏وَقَدْ ذَهَبَ بَعْضُ أَهْلِ ‏ ‏الْكُوفَةِ ‏ ‏إِلَى هَذَا الْحَدِيثِ مِنْهُمْ ‏ ‏وَكِيعُ بْنُ الْجَرَّاحِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7bf17664-bae0-5158-9fb2-c4089884ab8f', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '32', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏عَنْ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏الرُّبَيِّعِ بِنْتِ مُعَوِّذِ ابْنِ عَفْرَاءَ ‏ ‏أَنَّهَا رَأَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ قَالَتْ ‏ ‏مَسَحَ رَأْسَهُ وَمَسَحَ مَا أَقْبَلَ مِنْهُ وَمَا أَدْبَرَ وَصُدْغَيْهِ وَأُذُنَيْهِ مَرَّةً وَاحِدَةً ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏وَجَدِّ ‏ ‏طَلْحَةَ بْنِ مُصَرِّفِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَحَدِيثُ ‏ ‏الرُّبَيِّعِ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَقَدْ رُوِيَ ‏ ‏مِنْ غَيْرِ وَجْهٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏مَسَحَ بِرَأْسِهِ مَرَّةً ‏ ‏وَالْعَمَلُ عَلَى هَذَا عِنْدَ أَكْثَرِ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَنْ بَعْدَهُمْ ‏ ‏وَبِهِ يَقُولُ ‏ ‏جَعْفَرُ بْنُ مُحَمَّدٍ ‏ ‏وَسُفْيَانُ الثَّوْرِيُّ ‏ ‏وَابْنُ الْمُبَارَكِ ‏ ‏وَالشَّافِعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏رَأَوْا مَسْحَ الرَّأْسِ مَرَّةً وَاحِدَةً ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مَنْصُورٍ الْمَكِّيُّ ‏ ‏قَال سَمِعْتُ ‏ ‏سُفْيَانَ بْنَ عُيَيْنَةَ ‏ ‏يَقُولُ سَأَلْتُ ‏ ‏جَعْفَرَ بْنَ مُحَمَّدٍ ‏ ‏عَنْ مَسْحِ الرَّأْسِ أَيُجْزِئُ مَرَّةً فَقَالَ إِي وَاللَّهِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8f69f255-86ef-5700-adf9-08cdff3e7463', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '33', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ خَشْرَمٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏حَبَّانَ بْنِ وَاسِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏أَنَّهُ رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ وَأَنَّهُ مَسَحَ رَأْسَهُ بِمَاءٍ غَيْرِ ‏ ‏فَضْلِ ‏ ‏يَدَيْهِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَرَوَى ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏عَنْ ‏ ‏حَبَّانَ بْنِ وَاسِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ وَأَنَّهُ مَسَحَ رَأْسَهُ بِمَاءٍ غَيْرِ ‏ ‏فَضْلِ ‏ ‏يَدَيْهِ ‏ ‏وَرِوَايَةُ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏حَبَّانَ ‏ ‏أَصَحُّ لِأَنَّهُ قَدْ رُوِيَ مِنْ غَيْرِ وَجْهٍ هَذَا الْحَدِيثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏وَغَيْرِهِ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَذَ لِرَأْسِهِ مَاءً جَدِيدًا ‏ ‏وَالْعَمَلُ عَلَى هَذَا عِنْدَ أَكْثَرِ أَهْلِ الْعِلْمِ رَأَوْا أَنْ يَأْخُذَ لِرَأْسِهِ مَاءً جَدِيدًا ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('47331994-8e1b-59df-9861-79d718ce389b', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '34', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسَحَ بِرَأْسِهِ وَأُذُنَيْهِ ظَاهِرِهِمَا وَبَاطِنِهِمَا ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏الرُّبَيِّعِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَحَدِيثُ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَالْعَمَلُ عَلَى هَذَا عِنْدَ أَكْثَرِ أَهْلِ الْعِلْمِ يَرَوْنَ مَسْحَ الْأُذُنَيْنِ ظُهُورِهِمَا وَبُطُونِهِمَا ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e46d46f9-00dd-5da8-ad4f-db45f74ff85e', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '35', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏سِنَانِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏تَوَضَّأَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَغَسَلَ وَجْهَهُ ثَلَاثًا وَيَدَيْهِ ثَلَاثًا وَمَسَحَ بِرَأْسِهِ وَقَالَ الْأُذُنَانِ مِنْ الرَّأْسِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏قَالَ ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏لَا أَدْرِي هَذَا مِنْ قَوْلِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ مِنْ قَوْلِ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ لَيْسَ إِسْنَادُهُ بِذَاكَ ‏ ‏الْقَائِمِ وَالْعَمَلُ عَلَى هَذَا عِنْدَ أَكْثَرِ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَنْ بَعْدَهُمْ أَنَّ الْأُذُنَيْنِ مِنْ الرَّأْسِ ‏ ‏وَبِهِ يَقُولُ ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏وَابْنُ الْمُبَارَكِ ‏ ‏وَالشَّافِعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏و قَالَ ‏ ‏بَعْضُ أَهْلِ الْعِلْمِ مَا أَقْبَلَ مِنْ الْأُذُنَيْنِ فَمِنْ الْوَجْهِ وَمَا أَدْبَرَ فَمِنْ الرَّأْسِ ‏ ‏قَالَ ‏ ‏إِسْحَقُ ‏ ‏وَأَخْتَارُ أَنْ يَمْسَحَ مُقَدَّمَهُمَا مَعَ الْوَجْهِ وَمُؤَخَّرَهُمَا مَعَ رَأْسِهِ ‏ ‏و قَالَ ‏ ‏الشَّافِعِيُّ ‏ ‏هُمَا سُنَّةٌ عَلَى حِيَالِهِمَا يَمْسَحُهُمَا بِمَاءٍ جَدِيدٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9e86dc17-9ea6-5cb9-b643-1b930fbe5d36', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '36', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏وَهَنَّادٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي هَاشِمٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ لَقِيطِ بْنِ صَبِرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَضَّأْتَ ‏ ‏فَخَلِّلْ ‏ ‏الْأَصَابِعَ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَالْمُسَتَوْرِدِ وَهُوَ ابْنُ شَدَّادٍ الْفِهْرِيُّ ‏ ‏وَأبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَالْعَمَلُ عَلَى هَذَا عِنْدَ أَهْلِ الْعِلْمِ أَنَّهُ ‏ ‏يُخَلِّلُ ‏ ‏أَصَابِعَ رِجْلَيْهِ فِي الْوُضُوءِ ‏ ‏وَبِهِ يَقُولُ ‏ ‏أَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏قَالَ ‏ ‏إِسْحَقُ ‏ ‏يُخَلِّلُ ‏ ‏أَصَابِعَ يَدَيْهِ وَرِجْلَيْهِ فِي الْوُضُوءِ ‏ ‏وَأَبُو هَاشِمٍ ‏ ‏اسْمُهُ ‏ ‏إِسْمَعِيلُ بْنُ كَثِيرٍ الْمَكِّيُّ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1136b6e1-2a83-553b-8bd7-64286b0d4061', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '37', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعِيدٍ وَهُوَ الْجَوْهَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سَعْدُ بْنُ عَبْدِ الْحَمِيدِ بْنِ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَوَضَّأْتَ ‏ ‏فَخَلِّلْ ‏ ‏بَيْنَ أَصَابِعِ يَدَيْكَ وَرِجْلَيْكَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ غَرِيبٌ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f50c790b-a605-5d4a-b469-fa7cc7d662b7', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '38', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِيِّ ‏ ‏عَنْ ‏ ‏الْمُسْتَوْرِدِ بْنِ شَدَّادٍ الْفِهْرِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَضَّأَ دَلَكَ أَصَابِعَ رِجْلَيْهِ بِخِنْصَرِهِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ غَرِيبٌ ‏ ‏لَا نَعْرِفُهُ إِلَّا مِنْ حَدِيثِ ‏ ‏ابْنِ لَهِيعَةَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6acf94b3-e199-5b8a-a8b2-4aa2c30dce27', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '39', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏وَعَائِشَةَ ‏ ‏وَجَابِرٍ بْنِ عَبْدِ اللَّهِ بْنِ الْحَارِثِ هُوَ ابْنُ جَزْءٍ الزُّبَيْدِيُّ ‏ ‏وَمُعَيْقِيبٍ ‏ ‏وَخَالِدِ بْنِ الْوَلِيدِ ‏ ‏وَشُرَحْبِيلَ ابْنِ حَسَنَةَ ‏ ‏وَعَمْرِو بْنِ الْعَاصِ ‏ ‏وَيَزِيدَ بْنِ أَبِي سُفْيَانَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَقَدْ رُوِيَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏وَبُطُونِ الْأَقْدَامِ مِنْ النَّارِ ‏ ‏قَالَ ‏ ‏وَفِقْهُ هَذَا الْحَدِيثِ أَنَّهُ لَا يَجُوزُ الْمَسْحُ عَلَى الْقَدَمَيْنِ إِذَا لَمْ يَكُنْ عَلَيْهِمَا خُفَّانِ أَوْ جَوْرَبَانِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3addbc74-ad7d-5567-bccd-5ed40b253e90', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '40', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏وَهَنَّادٌ ‏ ‏وَقُتَيْبَةُ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏ح ‏ ‏قَالَ ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ مَرَّةً مَرَّةً ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏وَجَابِرٍ ‏ ‏وَبُرَيْدَةَ ‏ ‏وَأبِي رَافِعٍ ‏ ‏وَابْنِ الْفَاكِهِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَحَدِيثُ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَحْسَنُ شَيْءٍ فِي هَذَا الْبَابِ وَأَصَحُّ ‏ ‏وَرَوَى ‏ ‏رِشْدِينُ بْنُ سَعْدٍ ‏ ‏وَغَيْرُهُ هَذَا الْحَدِيثَ ‏ ‏عَنْ ‏ ‏الضَّحَّاكِ بْنِ شُرَحْبِيلَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ مَرَّةً مَرَّةً ‏ ‏قَالَ ‏ ‏وَلَيْسَ هَذَا بِشَيْءٍ وَالصَّحِيحُ ‏ ‏مَا رَوَى ‏ ‏ابْنُ عَجْلَانَ ‏ ‏وَهِشَامُ بْنُ سَعْدٍ ‏ ‏وَسُفْيَانُ الثَّوْرِيُّ ‏ ‏وَعَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4ca01df9-e5bc-5a2b-a972-7068ced8b5c4', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '41', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏وَمُحَمَّدُ بْنُ رَافِعٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زَيْدُ بْنُ حُبَابٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ ثَابِتِ بْنِ ثَوْبَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ الْفَضْلِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ هُرْمُزَ هُوَ الْأَعْرَجُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ مَرَّتَيْنِ مَرَّتَيْنِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ غَرِيبٌ ‏ ‏لَا نَعْرِفُهُ إِلَّا مِنْ حَدِيثِ ‏ ‏ابْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْفَضْلِ ‏ ‏وَهُوَ ‏ ‏إِسْنَادٌ حَسَنٌ صَحِيحٌ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَقَدْ رَوَى ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏عَامِرٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ ثَلَاثًا ثَلَاثًا ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fd8131ac-75f6-5f80-8607-ab42fd7b1bed', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '42', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏أَبِي حَيَّةَ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ ثَلَاثًا ثَلَاثًا ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏وَعَائِشَةَ ‏ ‏وَالرُّبَيِّعِ ‏ ‏وَابْنِ عُمَرَ ‏ ‏وَأَبِي أُمَامَةَ ‏ ‏وَأَبِي رَافِعٍ ‏ ‏وَعَبْدِ اللَّهِ بْنِ عَمْروٍ ‏ ‏وَمُعَاوِيَةَ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏وَجَابِرٍ ‏ ‏وَعَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏وَأُبَيِّ بْنِ كَعْبٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏عَلِيٍّ ‏ ‏أَحْسَنُ شَيْءٍ فِي هَذَا الْبَابِ وَأَصَحُّ ‏ ‏لِأَنَّهُ قَدْ رُوِيَ مِنْ غَيْرِ وَجْهٍ عَنْ ‏ ‏عَلِيٍّ ‏ ‏رِضْوَانُ اللَّهِ عَلَيْهِ ‏ ‏وَالْعَمَلُ عَلَى هَذَا عِنْدَ عَامَّةِ أَهْلِ الْعِلْمِ أَنَّ الْوُضُوءَ يُجْزِئُ مَرَّةً مَرَّةً وَمَرَّتَيْنِ أَفْضَلُ وَأَفْضَلُهُ ثَلَاثٌ وَلَيْسَ بَعْدَهُ شَيْءٌ ‏ ‏و قَالَ ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏لَا آمَنُ إِذَا زَادَ فِي الْوُضُوءِ عَلَى الثَّلَاثِ أَنْ يَأْثَمَ ‏ ‏و قَالَ ‏ ‏أَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏لَا يَزِيدُ عَلَى الثَّلَاثِ إِلَّا رَجُلٌ مُبْتَلًى ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('95d26574-f502-5c12-a4f2-0e8f46b952d8', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '43', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ مُوسَى الْفَزَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ أَبِي صَفِيَّةَ ‏ ‏قَالَ قُلْتُ ‏ ‏لِأَبِي جَعْفَرٍ ‏ ‏حَدَّثَكَ ‏ ‏جَابِرٌ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ مَرَّةً مَرَّةً وَمَرَّتَيْنِ مَرَّتَيْنِ وَثَلَاثًا ثَلَاثًا قَالَ نَعَمْ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَرَوَى ‏ ‏وَكِيعٌ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ أَبِي صَفِيَّةَ ‏ ‏قَالَ قُلْتُ ‏ ‏لِأَبِي جَعْفَرٍ ‏ ‏حَدَّثَكَ ‏ ‏جَابِرٌ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ مَرَّةً مَرَّةً قَالَ نَعَمْ ‏ ‏و حَدَّثَنَا ‏ ‏بِذَلِكَ ‏ ‏هَنَّادٌ ‏ ‏وَقُتَيْبَةُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ أَبِي صَفِيَّة ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَهَذَا ‏ ‏أَصَحُّ مِنْ حَدِيثِ ‏ ‏شَرِيكٍ ‏ ‏لِأَنَّهُ قَدْ رُوِيَ مِنْ غَيْرِ وَجْهٍ هَذَا عَنْ ‏ ‏ثَابِتٍ ‏ ‏نَحْوَ رِوَايَةِ ‏ ‏وَكِيعٍ ‏ ‏وَشَرِيكٌ ‏ ‏كَثِيرُ الْغَلَطِ ‏ ‏وَثَابِتُ بْنُ أَبِي صَفِيَّةَ ‏ ‏هُوَ ‏ ‏أَبُو حَمْزَةَ الثُّمَالِيُّ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('49955c99-e879-5d5b-8c80-80f3254e04be', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '44', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَغَسَلَ وَجْهَهُ ثَلَاثًا وَغَسَلَ يَدَيْهِ مَرَّتَيْنِ مَرَّتَيْنِ وَمَسَحَ بِرَأْسِهِ وَغَسَلَ رِجْلَيْهِ مَرَّتَيْنِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَقَدْ ذُكِرَ فِي غَيْرِ حَدِيثٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ بَعْضَ وُضُوئِهِ مَرَّةً وَبَعْضَهُ ثَلَاثًا ‏ ‏وَقَدْ رَخَّصَ بَعْضُ أَهْلِ الْعِلْمِ فِي ذَلِكَ لَمْ يَرَوْا بَأْسًا أَنْ يَتَوَضَّأَ الرَّجُلُ بَعْضَ وُضُوئِهِ ثَلَاثًا وَبَعْضَهُ مَرَّتَيْنِ أَوْ مَرَّةً ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('196261f0-d050-50df-80dc-52b0fba7c7f4', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '45', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏وَقُتَيْبَةُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏أَبِي حَيَّةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عَلِيًّا ‏ ‏تَوَضَّأَ فَغَسَلَ كَفَّيْهِ حَتَّى ‏ ‏أَنْقَاهُمَا ‏ ‏ثُمَّ مَضْمَضَ ثَلَاثًا وَاسْتَنْشَقَ ثَلَاثًا وَغَسَلَ وَجْهَهُ ثَلَاثًا وَذِرَاعَيْهِ ثَلَاثًا وَمَسَحَ بِرَأْسِهِ مَرَّةً ثُمَّ غَسَلَ قَدَمَيْهِ إِلَى ‏ ‏الْكَعْبَيْنِ ‏ ‏ثُمَّ قَامَ فَأَخَذَ ‏ ‏فَضْلَ ‏ ‏طَهُورِهِ فَشَرِبَهُ وَهُوَ قَائِمٌ ثُمَّ قَالَ أَحْبَبْتُ أَنْ أُرِيَكُمْ كَيْفَ كَانَ طُهُورُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏وَعَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏وَعَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏وَالرُّبَيِّعِ ‏ ‏وَعَبْدِ اللَّهِ بْنِ أُنَيْسٍ ‏ ‏وَعَائِشَةَ ‏ ‏رِضْوَانُ اللَّهِ عَلَيْهِمْ ‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏وَهَنَّادٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَبْدِ خَيْرٍ ‏ ‏ذَكَرَ عَنْ ‏ ‏عَلِيٍّ ‏ ‏مِثْلَ حَدِيثِ ‏ ‏أَبِي حَيَّةَ ‏ ‏إِلَّا أَنَّ ‏ ‏عَبْدَ خَيْرٍ ‏ ‏قَالَ ‏ ‏كَانَ إِذَا فَرَغَ مِنْ طُهُورِهِ أَخَذَ مِنْ ‏ ‏فَضْلِ ‏ ‏طَهُورِهِ بِكَفِّهِ فَشَرِبَهُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏عَلِيٍّ ‏ ‏رَوَاهُ ‏ ‏أَبُو إِسْحَقَ الْهَمْدَانِيُّ ‏ ‏عَنْ ‏ ‏أَبِي حَيَّةَ ‏ ‏وَعَبْدِ خَيْرٍ ‏ ‏وَالْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏وَقَدْ رَوَاهُ ‏ ‏زَائِدَةُ بْنُ قُدَامَةَ ‏ ‏وَغَيْرُ وَاحِدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ خَيْرٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حَدِيثَ الْوُضُوءِ ‏ ‏بِطُولِهِ ‏ ‏وَهَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏قَالَ ‏ ‏وَرَوَى ‏ ‏شُعْبَةُ ‏ ‏هَذَا الْحَدِيثَ عَنْ ‏ ‏خَالِدِ بْنِ عَلْقَمَةَ ‏ ‏فَأَخْطَأَ فِي اسْمِهِ وَاسْمِ أَبِيهِ فَقَالَ ‏ ‏مَالِكُ بْنُ عُرْفُطَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ خَيْرٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏وَرُوِيَ عَنْ ‏ ‏أَبِي عَوَانَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ خَيْرٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏وَرُوِيَ عَنْهُ عَنْ ‏ ‏مَالِكِ بْنِ عُرْفُطَةَ ‏ ‏مِثْلُ رِوَايَةِ ‏ ‏شُعْبَةَ ‏ ‏وَالصَّحِيحُ ‏ ‏خَالِدُ بْنُ عَلْقَمَةَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2856c982-6f84-594b-b722-b5e9d4ca96a6', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '46', '‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ عَلِيٍّ الْجَهْضَمِيُّ ‏ ‏وَأَحْمَدُ بْنُ أَبِي عُبَيْدِ اللَّهِ السَّلِيمِيُّ الْبَصْرِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو قُتَيْبَةَ سَلْمُ بْنُ قُتَيْبَةَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ بْنِ عَلِيٍّ الْهَاشِمِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏جَاءَنِي ‏ ‏جِبْرِيلُ ‏ ‏فَقَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏إِذَا تَوَضَّأْتَ ‏ ‏فَانْتَضِحْ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ غَرِيبٌ ‏ ‏قَالَ ‏ ‏و سَمِعْت ‏ ‏مُحَمَّدًا ‏ ‏يَقُولُ ‏ ‏الْحَسَنُ بْنُ عَلِيٍ الْهَاشِمِيُّ ‏ ‏مُنْكَرُ الْحَدِيثِ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أَبِي الْحَكَمِ بْنِ سُفْيَانَ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏وَزَيْدِ بْنِ حَارِثَةَ ‏ ‏وَأَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏و قَالَ ‏ ‏بَعْضُهُمْ ‏ ‏سُفْيَانُ بْنُ الْحَكَمِ ‏ ‏أَوْ ‏ ‏الْحَكَمُ بْنُ سُفْيَانَ ‏ ‏وَاضْطَرَبُوا فِي هَذَا الْحَدِيثِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('60359b9f-f513-5b3d-8414-2ad3bff36d5f', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '47', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حُجْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَعِيلُ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلَا أَدُلُّكُمْ عَلَى مَا يَمْحُو اللَّهُ بِهِ الْخَطَايَا وَيَرْفَعُ بِهِ الدَّرَجَاتِ قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ ‏ ‏إِسْبَاغُ ‏ ‏الْوُضُوءِ عَلَى الْمَكَارِهِ وَكَثْرَةُ ‏ ‏الْخُطَا إِلَى الْمَسَاجِدِ وَانْتِظَارُ الصَّلَاةِ بَعْدَ الصَّلَاةِ فَذَلِكُمْ ‏ ‏الرِّبَاطُ ‏ ‏و حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ ‏ ‏نَحْوَهُ ‏ ‏و قَالَ ‏ ‏قُتَيْبَةُ ‏ ‏فِي حَدِيثِهِ ‏ ‏فَذَلِكُمْ ‏ ‏الرِّبَاطُ ‏ ‏فَذَلِكُمْ ‏ ‏الرِّبَاطُ ‏ ‏فَذَلِكُمْ ‏ ‏الرِّبَاطُ ‏ ‏ثَلَاثًا ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏وَعَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏وَعَبِيدَةَ وَيُقَالُ عُبَيْدَةُ بْنُ عَمْرٍو ‏ ‏وَعَائِشَةَ ‏ ‏وَعَبْدِ الرَّحْمَنِ بْنِ عَائِشٍ الْحَضْرَمِيِّ ‏ ‏وَأَنَسٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَحَدِيثُ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فِي هَذَا الْبَابِ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَالْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏هُوَ ‏ ‏ابْنُ يَعْقُوبَ الْجُهَنِيُّ الْحُرَقِيُّ ‏ ‏وَهُوَ ثِقَةٌ عِنْدَ أَهْلِ الْحَدِيثِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7d87aa7e-e29b-5e9e-ba10-1d56ec797837', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '48', '‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ وَكِيعِ بْنِ الْجَرَّاحِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ حُبَابٍ ‏ ‏عَنْ ‏ ‏أَبِي مُعَاذٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خِرْقَةٌ يُنَشِّفُ بِهَا بَعْدَ الْوُضُوءِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏عَائِشَةَ ‏ ‏لَيْسَ بِالْقَائِمِ وَلَا يَصِحُّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي هَذَا الْبَابِ شَيْءٌ ‏ ‏وَأَبُو مُعَاذٍ ‏ ‏يَقُولُونَ هُوَ ‏ ‏سُلَيْمَانُ بْنُ أَرْقَمَ ‏ ‏وَهُوَ ضَعِيفٌ عِنْدَ أَهْلِ الْحَدِيثِ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏مُعَاذِ بْنِ جَبَلٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c787118e-f082-569f-b6cd-e903dd8ccac2', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '49', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏رِشْدِينُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ زِيَادِ بْنِ أَنْعُمٍ ‏ ‏عَنْ ‏ ‏عُتْبَةَ بْنِ حُمَيْدٍ ‏ ‏عَنْ ‏ ‏عُبَادَةَ بْنِ نُسَيٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ ‏ ‏عَنْ ‏ ‏مُعَاذِ بْنِ جَبَلٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏تَوَضَّأَ مَسَحَ وَجْهَهُ بِطَرَفِ ثَوْبِهِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ غَرِيبٌ وَإِسْنَادُهُ ضَعِيفٌ ‏ ‏وَرِشْدِينُ بْنُ سَعْدٍ ‏ ‏وَعَبْدُ الرَّحْمَنِ بْنُ زِيَادِ بْنِ أَنْعُمٍ الْأَفْرِيقِيُّ ‏ ‏يُضَعَّفَانِ فِي الْحَدِيثِ ‏ ‏وَقَدْ رَخَّصَ قَوْمٌ مِنْ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَنْ بَعْدَهُمْ فِي ‏ ‏التَّمَنْدُلِ ‏ ‏بَعْدَ الْوُضُوءِ وَمَنْ كَرِهَهُ إِنَّمَا كَرِهَهُ مِنْ قِبَلِ أَنَّهُ قِيلَ إِنَّ الْوُضُوءَ يُوزَنُ ‏ ‏وَرُوِيَ ذَلِكَ عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيِّبِ ‏ ‏وَالزُّهْرِيِّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حُمَيْدٍ الرَّازِيُّ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏قَالَ حَدَّثَنِيهِ ‏ ‏عَلِيُّ بْنُ مُجَاهِدٍ ‏ ‏عَنِّي ‏ ‏وَهُوَ عِنْدِي ثِقَةٌ ‏ ‏عَنْ ‏ ‏ثَعْلَبَة ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ ‏ ‏إِنَّمَا كُرِهَ الْمِنْدِيلُ بَعْدَ الْوُضُوءِ لِأَنَّ الْوُضُوءَ يُوزَنُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('eaf28f37-8366-5605-8956-11473a48c331', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '50', '‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ مُحَمَّدِ بْنِ عِمْرَانَ الثَّعْلَبِيُّ الْكُوفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ حُبَابٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ يَزِيدَ الدِّمَشْقِيِّ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ الْخَوْلَانِيِّ ‏ ‏وَأَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ ثُمَّ قَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ اللَّهُمَّ اجْعَلْنِي مِنْ التَّوَّابِينَ وَاجْعَلْنِي مِنْ الْمُتَطَهِّرِينَ فُتِحَتْ لَهُ ثَمَانِيَةُ أَبْوَابِ الْجَنَّةِ يَدْخُلُ مِنْ أَيِّهَا شَاءَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏وَعُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏عُمَرَ ‏ ‏قَدْ خُولِفَ ‏ ‏زَيْدُ بْنُ حُبَابٍ ‏ ‏فِي هَذَا الْحَدِيثِ ‏ ‏قَالَ ‏ ‏وَرَوَى ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏وَغَيْرُهُ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏وَعَنْ ‏ ‏رَبِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏وَهَذَا ‏ ‏حَدِيثٌ فِي إِسْنَادِهِ اضْطِرَابٌ ‏ ‏وَلَا يَصِحُّ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي هَذَا الْبَابِ كَبِيرُ شَيْءٍ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏وَأَبُو إِدْرِيسَ ‏ ‏لَمْ يَسْمَعْ مِنْ ‏ ‏عُمَرَ ‏ ‏شَيْئًا ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('85bc054f-d02e-576d-a59d-7ef8381de0ff', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '51', '‏ ‏و حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ مَنِيعٍ ‏ ‏وَعَليُّ بْنُ حُجْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ابْنُ عُلَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي رَيْحَانَةَ ‏ ‏عَنْ ‏ ‏سَفِينَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَوَضَّأُ ‏ ‏بِالْمُدِّ ‏ ‏وَيَغْتَسِلُ ‏ ‏بِالصَّاعِ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَجَابِرٍ ‏ ‏وَأَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏سَفِينَةَ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَأَبُو رَيْحَانَةَ ‏ ‏اسْمُهُ ‏ ‏عَبْدُ اللَّهِ بْنُ مَطَرٍ ‏ ‏وَهَكَذَا رَأَى بَعْضُ أَهْلِ الْعِلْمِ الْوُضُوءَ ‏ ‏بِالْمُدِّ ‏ ‏وَالْغُسْلَ ‏ ‏بِالصَّاعِ ‏ ‏و قَالَ ‏ ‏الشَّافِعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏لَيْسَ مَعْنَى هَذَا الْحَدِيثِ عَلَى التَّوَقِّي أَنَّهُ لَا يَجُوزُ أَكْثَرُ مِنْهُ وَلَا أَقَلُّ مِنْهُ وَهُوَ قَدْرُ مَا يَكْفِي ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('de5f7e4c-6b6c-5ee0-9326-49b10facaf17', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '52', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاودَ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏خَارِجَةُ بْنُ مُصْعَبٍ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عُتَيِّ بْنِ ضَمْرَةَ السَّعْدِيِّ ‏ ‏عَنْ ‏ ‏أُبَيِّ بْنِ كَعْبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ لِلْوُضُوءِ شَيْطَانًا يُقَالُ لَهُ الْوَلَهَانُ فَاتَّقُوا وَسْوَاسَ الْمَاءِ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏وَعَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏أُبَيِّ بْنِ كَعْبٍ ‏ ‏حَدِيثٌ غَرِيبٌ وَلَيْسَ إِسْنَادُهُ بِالْقَوِيِّ ‏ ‏عِنْدَ أَهْلِ الْحَدِيثِ ‏ ‏لَأَنَّا لَا نَعْلَمُ أَحَدًا أَسْنَدَهُ غَيْرَ خَارِجَةَ وَقَدْ رُوِيَ هَذَا الْحَدِيثُ مِنْ غَيْرِ وَجْهٍ عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَوْلَهُ وَلَا يَصِحُّ فِي هَذَا الْبَابِ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْءٌ ‏ ‏وَخَارِجَةُ ‏ ‏لَيْسَ بِالْقَوِيِّ عِنْدَ أَصْحَابِنَا وَضَعَّفَهُ ‏ ‏ابْنُ الْمُبَارَكِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9460adc9-925e-5d21-8228-ba9f2d611e25', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '53', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حُمَيْدٍ الرَّازِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سَلَمَةُ بْنُ الْفَضْلِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَوَضَّأُ لِكُلِّ صَلَاةٍ طَاهِرًا أَوْ غَيْرَ طَاهِرٍ ‏ ‏قَالَ قُلْتُ ‏ ‏لِأَنَسٍ ‏ ‏فَكَيْفَ كُنْتُمْ تَصْنَعُونَ أَنْتُمْ قَالَ كُنَّا نَتَوَضَّأُ وُضُوءًا وَاحِدًا ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَحَدِيثُ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏حَدِيثٌ حَسَنٌ غَرِيبٌ ‏ ‏مِنْ هَذَا الْوَجْهِ ‏ ‏وَالْمَشْهُورُ عَنْدَ أَهْلِ الْحَدِيثِ حَدِيثُ ‏ ‏عَمْرِو بْنِ عَامِرٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏وَقَدْ كَانَ بَعْضُ أَهْلِ الْعِلْمِ يَرَى الْوُضُوءَ لِكُلِّ صَلَاةٍ اسْتِحْبَابًا لَا عَلَى الْوُجُوبِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b35a41ed-a2ba-5bfa-9cc7-ca0d7d83beeb', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '54', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏وَعَبْدُ الرَّحْمَنِ هُوَ ابْنُ مَهْدِيٍّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَامِرٍ الْأنْصَارِيِّ ‏ ‏قَال سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ عِنْدَ كُلِّ صَلَاةٍ ‏ ‏قُلْتُ ‏ ‏فَأَنْتُمْ مَا كُنْتُمْ تَصْنَعُونَ قَالَ كُنَّا نُصَلِّي الصَّلَوَاتِ كُلَّهَا بِوُضُوءٍ وَاحِدٍ مَا لَمْ نُحْدِثْ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَحَدِيثُ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏حَدِيثٌ جَيِّدٌ غَرِيبٌ حَسَنٌ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('98062d80-756f-5dfd-97b3-876bc1ca2005', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '55', '‏ ‏وَقَدْ رُوِيَ فِي حَدِيثٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ تَوَضَّأَ عَلَى طُهْرٍ كَتَبَ اللَّهُ لَهُ بِهِ عَشْرَ حَسَنَاتٍ ‏ ‏قَالَ ‏ ‏وَرَوَى ‏ ‏هَذَا الْحَدِيثَ ‏ ‏الْأَفْرِيقِيُّ ‏ ‏عَنْ ‏ ‏أَبِي غُطَيْفٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏بِذَلِكَ ‏ ‏الْحُسَيْنُ بْنُ حُرَيْثٍ الْمَرْوَزِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ الْوَاسِطِيُّ ‏ ‏عَنْ ‏ ‏الْأَفْرِيقِيِّ ‏ ‏وَهُوَ ‏ ‏إِسْنَادٌ ضَعِيفٌ ‏ ‏قَالَ ‏ ‏عَلِيُّ بْنُ الْمَدِينِيِّ ‏ ‏قَالَ ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْقَطَّانُ ‏ ‏ذَكَرَ ‏ ‏لِهِشَامِ بْنِ عُرْوَةَ ‏ ‏هَذَا الْحَدِيثُ فَقَالَ هَذَا إِسْنَادٌ ‏ ‏مَشْرِقِيٌ ‏ ‏قَالَ ‏ ‏سَمِعْت ‏ ‏أَحْمَدَ بْنَ الْحَسَنِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَحْمَدَ بْنَ حَنْبَلٍ ‏ ‏يَقُولُ ‏ ‏مَا رَأَيْتُ بِعَيْنِي مِثْلَ ‏ ‏يَحْيَى بْنِ سَعِيدٍ الْقَطَّانِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fa384ddf-1be5-5e4c-a459-04274881fd42', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '56', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ لِكُلِّ صَلَاةٍ فَلَمَّا كَانَ عَامُ الْفَتْحِ صَلَّى الصَّلَوَاتِ كُلَّهَا بِوُضُوءٍ وَاحِدٍ وَمَسَحَ عَلَى خُفَّيْهِ فَقَالَ ‏ ‏عُمَرُ ‏ ‏إِنَّكَ فَعَلْتَ شَيْئًا لَمْ تَكُنْ فَعَلْتَهُ قَالَ عَمْدًا فَعَلْتُهُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَرَوَى ‏ ‏هَذَا الْحَدِيثَ ‏ ‏عَلِيُّ بْنُ قَادِمٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏وَزَادَ فِيهِ تَوَضَّأَ مَرَّةً مَرَّةً ‏ ‏قَالَ ‏ ‏وَرَوَى ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏هَذَا الْحَدِيثَ أَيْضًا ‏ ‏عَنْ ‏ ‏مُحَارِبِ بْنِ دِثَارٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ بُرَيْدَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَوَضَّأُ لِكُلِّ صَلَاةٍ ‏ ‏وَرَوَاهُ ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مُحَارِبٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏وَرَوَاهُ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏وَغَيْرُهُ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مُحَارِبِ بْنِ دِثَارٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ بُرَيْدَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُرْسَلًا ‏ ‏وَهَذَا أَصَحُّ مِنْ حَدِيثِ ‏ ‏وَكِيعٍ ‏ ‏وَالْعَمَلُ عَلَى هَذَا عِنْدَ أَهْلِ الْعِلْمِ أَنَّهُ ‏ ‏يُصَلِّي الصَّلَوَاتِ بِوُضُوءٍ وَاحِدٍ مَا لَمْ يُحْدِثْ وَكَانَ بَعْضُهُمْ يَتَوَضَّأُ لِكُلِّ صَلَاةٍ اسْتِحْبَابًا وَإِرَادَةَ الْفَضْلِ ‏ ‏وَيُرْوَى عَنْ ‏ ‏الْأَفْرِيقِيِّ ‏ ‏عَنْ ‏ ‏أَبِي غُطَيْفٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَوَضَّأَ عَلَى طُهْرٍ كَتَبَ اللَّهُ لَهُ بِهِ عَشْرَ حَسَنَاتٍ ‏ ‏وَهَذَا ‏ ‏إِسْنَادٌ ضَعِيفٌ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الظُّهْرَ وَالْعَصْرَ بِوُضُوءٍ وَاحِدٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('12e132b4-84cc-5aa9-a516-270046f8898c', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '57', '‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِي الشَّعْثَاءِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏مَيْمُونَةُ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ مِنْ الْجَنَابَةِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَهُوَ قَوْلُ عَامَّةِ الْفُقَهَاءِ أَنْ لَا بَأْسَ أَنْ يَغْتَسِلَ الرَّجُلُ وَالْمَرْأَةُ مِنْ إِنَاءٍ وَاحِدٍ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏وَعَائِشَةَ ‏ ‏وَأَنَسٍ ‏ ‏وَأُمِّ هَانِئٍ ‏ ‏وَأُمِّ صُبَيَّةَ الْجُهَنِيَّةِ ‏ ‏وَأُمِّ سَلَمَةَ ‏ ‏وَابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَأَبُو الشَّعْثَاءِ ‏ ‏اسْمُهُ ‏ ‏جَابِرُ بْنُ زَيْدٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('062133de-cb8e-50aa-a8e2-50d7c730bacb', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '58', '‏ ‏حَدَّثَنَا ‏ ‏مَحْمُودُ بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي حَاجِبٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي غِفَارٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏فَضْلِ ‏ ‏طَهُورِ الْمَرْأَةِ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَرْجِسَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَكَرِهَ بَعْضُ الْفُقَهَاءِ الْوُضُوءَ ‏ ‏بِفَضْلِ ‏ ‏طَهُورِ الْمَرْأَةِ وَهُوَ قَوْلُ ‏ ‏أَحْمَدَ ‏ ‏وَإِسْحَقَ ‏ ‏كَرِهَا ‏ ‏فَضْلَ ‏ ‏طَهُورِهَا وَلَمْ يَرَيَا ‏ ‏بِفَضْلِ سُؤْرِهَا ‏ ‏بَأْسًا ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8c4b2fff-7a4f-5c16-96ea-36d481a2edeb', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '59', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏وَمَحْمُودُ بْنُ غَيْلَانَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏قَال سَمِعْتُ ‏ ‏أَبَا حَاجِبٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏الْحَكَمِ بْنِ عَمْرٍو الْغِفَارِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يَتَوَضَّأَ الرَّجُلُ ‏ ‏بِفَضْلِ ‏ ‏طَهُورِ الْمَرْأَةِ ‏ ‏أَوْ قَالَ ‏ ‏بِسُؤْرِهَا ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ ‏ ‏وَأَبُو حَاجِبٍ ‏ ‏اسْمُهُ ‏ ‏سَوَادَةُ بْنُ عَاصِمٍ ‏ ‏و قَالَ ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏فِي حَدِيثِهِ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَتَوَضَّأَ الرَّجُلُ ‏ ‏بِفَضْلِ ‏ ‏طَهُورِ الْمَرْأَةِ ‏ ‏وَلَمْ يَشُكَّ فِيهِ ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('987aaaa4-a2f1-5b6c-a37d-f57ea21f0726', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '60', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏اغْتَسَلَ بَعْضُ أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏جَفْنَةٍ ‏ ‏فَأَرَادَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَتَوَضَّأَ مِنْهُ فَقَالَتْ يَا رَسُولَ اللَّهِ إِنِّي كُنْتُ جُنُبًا فَقَالَ ‏ ‏إِنَّ الْمَاءَ لَا يُجْنِبُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَهُوَ قَوْلُ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏وَمَالِكٍ ‏ ‏وَالشَّافِعِيِّ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d9079c00-d2cf-5797-94cf-c876df41df55', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '61', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏وَالْحَسَنُ بْنُ عَلِيٍّ الْخَلَّالُ ‏ ‏وَغَيْرُ وَاحِدٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ رَافِعِ بْنِ خَدِيجٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ أَنَتَوَضَّأُ مِنْ بِئْرِ ‏ ‏بُضَاعَةَ ‏ ‏وَهِيَ بِئْرٌ يُلْقَى فِيهَا الْحِيَضُ وَلُحُومُ الْكِلَابِ وَالنَّتْنُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمَاءَ طَهُورٌ لَا يُنَجِّسُهُ شَيْءٌ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ ‏ ‏وَقَدْ جَوَّدَ ‏ ‏أَبُو أُسَامَةَ ‏ ‏هَذَا الْحَدِيثَ فَلَمْ يَرْوِ أَحَدٌ حَدِيثَ ‏ ‏أَبِي سَعِيدٍ ‏ ‏فِي بِئْرِ ‏ ‏بُضَاعَةَ ‏ ‏أَحْسَنَ مِمَّا رَوَى ‏ ‏أَبُو أُسَامَةَ ‏ ‏وَقَدْ رُوِيَ هَذَا الْحَدِيثُ مِنْ غَيْرِ وَجْهٍ عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَعَائِشَةَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('62c679cf-e623-5556-a4cb-3e0afda3159b', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '62', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يُسْأَلُ عَنْ الْمَاءِ يَكُونُ فِي الْفَلَاةِ مِنْ الْأَرْضِ وَمَا يَنُوبُهُ مِنْ ‏ ‏السِّبَاعِ ‏ ‏وَالدَّوَابِّ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ الْمَاءُ قُلَّتَيْنِ لَمْ يَحْمِلْ ‏ ‏الْخَبَثَ ‏ ‏قَالَ ‏ ‏عَبْدَةُ ‏ ‏قَالَ ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏الْقُلَّةُ هِيَ الْجِرَارُ وَالْقُلَّةُ الَّتِي ‏ ‏يُسْتَقَى فِيهَا ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَهُوَ قَوْلُ ‏ ‏الشَّافِعِيِّ ‏ ‏وَأَحْمَدَ ‏ ‏وَإِسْحَقَ ‏ ‏قَالُوا إِذَا كَانَ الْمَاءُ ‏ ‏قُلَّتَيْنِ ‏ ‏لَمْ يُنَجِّسْهُ شَيْءٌ مَا لَمْ يَتَغَيَّرْ رِيحُهُ أَوْ طَعْمُهُ وَقَالُوا يَكُونُ نَحْوًا مِنْ خَمْسِ ‏ ‏قِرَبٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c09396a5-616c-5f74-a315-becfc895380e', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '63', '‏ ‏حَدَّثَنَا ‏ ‏مَحْمُودُ بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَبُولَنَّ أَحَدُكُمْ فِي الْمَاءِ ‏ ‏الدَّائِمِ ‏ ‏ثُمَّ يَتَوَضَّأُ مِنْهُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('42d3b333-19b9-518c-9c97-9ac4bfd7b493', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '64', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏الْأَنْصَارِيُّ إِسْحَقُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏مَعْنٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ سَلَمَةَ ‏ ‏مِنْ ‏ ‏آلِ ابْنِ الْأَزْرَقِ ‏ ‏أَنَّ ‏ ‏الْمُغِيرَةَ بْنَ أَبِي بُرْدَةَ ‏ ‏وَهُوَ مِنْ ‏ ‏بَنِي عَبْدِ الدَّارِ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَأَلَ رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّا نَرْكَبُ الْبَحْرَ وَنَحْمِلُ مَعَنَا الْقَلِيلَ مِنْ الْمَاءِ فَإِنْ تَوَضَّأْنَا بِهِ عَطِشْنَا أَفَنَتَوَضَّأُ مِنْ مَاءِ الْبَحْرِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ الطَّهُورُ مَاؤُهُ الْحِلُّ مَيْتَتُهُ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏وَالْفِرَاسِيِّ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَهُوَ قَوْلُ أَكْثَرِ الْفُقَهَاءِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهُمْ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَابْنُ عَبَّاسٍ ‏ ‏لَمْ يَرَوْا بَأْسًا بِمَاءِ الْبَحْرِ ‏ ‏وَقَدْ كَرِهَ بَعْضُ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوُضُوءَ بِمَاءِ الْبَحْرِ مِنْهُمْ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏وَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏هُوَ نَارٌ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('08f4d17e-f53a-5373-b6a2-86d1157431e7', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '65', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏وَقُتَيْبَةُ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏قَال سَمِعْتُ ‏ ‏مُجَاهِدًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ عَلَى قَبْرَيْنِ فَقَالَ ‏ ‏إِنَّهُمَا يُعَذَّبَانِ وَمَا يُعَذَّبَانِ فِي كَبِيرٍ أَمَّا هَذَا فَكَانَ لَا ‏ ‏يَسْتَتِرُ ‏ ‏مِنْ بَوْلِهِ وَأَمَّا هَذَا فَكَانَ يَمْشِي ‏ ‏بِالنَّمِيمَةِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَأَبِي مُوسَى ‏ ‏وَعَبْدِ الرَّحْمَنِ بْنِ حَسَنَةَ ‏ ‏وَزَيْدِ بْنِ ثَابِتٍ ‏ ‏وَأَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَرَوَى ‏ ‏مَنْصُورٌ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَلَمْ يَذْكُرْ فِيهِ عَنْ ‏ ‏طَاوُسٍ ‏ ‏وَرِوَايَةُ ‏ ‏الْأَعْمَشِ ‏ ‏أَصَحُّ ‏ ‏قَالَ ‏ ‏و سَمِعْت ‏ ‏أَبَا بَكْرٍ مُحَمَّدَ بْنَ أَبَانَ الْبَلْخِيَّ ‏ ‏مُسْتَمْلِي ‏ ‏وَكِيعٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏وَكِيعًا ‏ ‏يَقُولُ ‏ ‏الْأَعْمَشُ ‏ ‏أَحْفَظُ لِإِسْنَادِ ‏ ‏إِبْرَاهِيمَ ‏ ‏مِنْ ‏ ‏مَنْصُورٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('27a73b62-d1c5-54e6-8970-a4fac8a2a538', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '66', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏وَأَحْمَدُ بْنُ مَنِيعٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏أُمِّ قَيْسٍ بِنْتِ مِحْصَنٍ ‏ ‏قَالَتْ ‏ ‏دَخَلْتُ بِابْنٍ لِي عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَأْكُلْ الطَّعَامَ ‏ ‏فَبَالَ عَلَيْهِ فَدَعَا بِمَاءٍ فَرَشَّهُ عَلَيْهِ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏وَعَائِشَةَ ‏ ‏وَزَيْنَبَ ‏ ‏وَلُبَابَةَ بِنْتِ الْحَارِثِ ‏ ‏وَهِيَ ‏ ‏أُمُّ الْفَضْلِ بْنِ عَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏وَأَبِي السَّمْحِ ‏ ‏وَعَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏وَأَبِي لَيْلَى ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَهُوَ قَوْلُ غَيْرِ وَاحِدٍ مِنْ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ وَمَنْ بَعْدَهُمْ مِثْلِ ‏ ‏أَحْمَدَ ‏ ‏وَإِسْحَقَ ‏ ‏قَالُوا ‏ ‏يُنْضَحُ ‏ ‏بَوْلُ الْغُلَامِ وَيُغْسَلُ بَوْلُ الْجَارِيَةِ وَهَذَا مَا لَمْ يَطْعَمَا فَإِذَا طَعِمَا غُسِلَا جَمِيعًا ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('26327111-78a9-5eff-8054-e46dc7d85192', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '67', '‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ مُحَمَّدٍ الزَّعْفَرَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏وَقَتَادَةُ ‏ ‏وَثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ نَاسًا مِنْ ‏ ‏عُرَيْنَةَ ‏ ‏قَدِمُوا ‏ ‏الْمَدِينَةَ ‏ ‏فَاجْتَوَوْهَا ‏ ‏فَبَعَثَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي إِبِلِ الصَّدَقَةِ وَقَالَ اشْرَبُوا مِنْ أَلْبَانِهَا وَأَبْوَالِهَا فَقَتَلُوا رَاعِيَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاسْتَاقُوا الْإِبِلَ وَارْتَدُّوا عَنْ الْإِسْلَامِ فَأُتِيَ بِهِمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَطَعَ أَيْدِيَهُمْ وَأَرْجُلَهُمْ مِنْ خِلَافٍ ‏ ‏وَسَمَرَ أَعْيُنَهُمْ ‏ ‏وَأَلْقَاهُمْ ‏ ‏بِالْحَرَّةِ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏فَكُنْتُ ‏ ‏أَرَى أَحَدَهُمْ ‏ ‏يَكُدُّ ‏ ‏الْأَرْضَ بِفِيهِ حَتَّى مَاتُوا ‏ ‏وَرُبَّمَا ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏يَكْدُمُ ‏ ‏الْأَرْضَ بِفِيهِ حَتَّى مَاتُوا ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَقَدْ رُوِيَ مِنْ غَيْرِ وَجْهٍ عَنْ ‏ ‏أَنَسٍ ‏ ‏وَهُوَ قَوْلُ أَكْثَرِ أَهْلِ الْعِلْمِ قَالُوا لَا بَأْسَ بِبَوْلِ مَا يُؤْكَلُ لَحْمُهُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fa195c2c-0a07-502e-8339-a1d40dea5aed', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '68', '‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ سَهْلٍ الْأَعْرَجُ الْبَغْدَادِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْتَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏إِنَّمَا ‏ ‏سَمَلَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْيُنَهُمْ لِأَنَّهُمْ ‏ ‏سَمَلُوا ‏ ‏أَعْيُنَ الرُّعَاةِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ غَرِيبٌ ‏ ‏لَا نَعْلَمُ أَحَدًا ذَكَرَهُ غَيْرَ هَذَا الشَّيْخِ عَنْ ‏ ‏يَزِيدَ بْنِ زُرَيْعٍ ‏ ‏وَهُوَ مَعْنَى قَوْلِهِ ‏ { ‏وَالْجُرُوحَ ‏ ‏قِصَاصٌ ‏ } ‏وَقَدْ رُوِيَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏قَالَ إِنَّمَا فَعَلَ بِهِمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا قَبْلَ أَنْ تَنْزِلَ ‏ ‏الْحُدُودُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5d0a6826-9535-51a1-a187-d57091f26dcc', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '69', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏وَهَنَّادٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا وُضُوءَ إِلَّا مِنْ صَوْتٍ أَوْ رِيحٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b229d49d-61b8-5727-95de-6c50faf1f7f4', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '70', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ فِي الْمَسْجِدِ فَوَجَدَ رِيحًا بَيْنَ أَلْيَتَيْهِ فَلَا يَخْرُجْ حَتَّى يَسْمَعَ صَوْتًا أَوْ يَجِدَ رِيحًا ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏وَعَلِيِّ بْنِ طَلْقٍ ‏ ‏وَعَائِشَةَ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏وَابْنِ مَسْعُودٍ ‏ ‏وَأَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَهُوَ قَوْلُ الْعُلَمَاءِ أَنْ لَا يَجِبَ عَلَيْهِ الْوُضُوءُ إِلَّا مِنْ حَدَثٍ يَسْمَعُ صَوْتًا أَوْ يَجِدُ رِيحًا ‏ ‏و قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏إِذَا شَكَّ فِي الْحَدَثِ فَإِنَّهُ لَا يَجِبُ عَلَيْهِ الْوُضُوءُ حَتَّى يَسْتَيْقِنَ اسْتِيقَانًا يَقْدِرُ أَنْ يَحْلِفَ عَلَيْهِ وَقَالَ إِذَا خَرَجَ مِنْ قُبُلِ الْمَرْأَةِ الرِّيحُ وَجَبَ عَلَيْهَا الْوُضُوءُ ‏ ‏وَهُوَ قَوْلُ ‏ ‏الشَّافِعِيِّ ‏ ‏وَإِسْحَقَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2aecda84-bd82-5dd1-a634-58311930b5cd', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '71', '‏ ‏حَدَّثَنَا ‏ ‏مَحْمُودُ بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ لَا يَقْبَلُ صَلَاةَ أَحَدِكُمْ إِذَا أَحْدَثَ حَتَّى يَتَوَضَّأَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4a3f528f-0996-5338-a031-d3f75a3ae60a', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '72', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ مُوسَى ‏ ‏كُوفِيٌّ ‏ ‏وَهَنَّادٌ ‏ ‏وَمُحَمَّدُ بْنُ عُبَيْدٍ الْمُحَارِبِيُّ ‏ ‏الْمَعْنَى وَاحِدٌ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏عَبْدُ السَّلَامِ بْنُ حَرْبٍ الْمُلَائِيُّ ‏ ‏عَنْ ‏ ‏أَبِي خَالِدٍ الدَّالَانِيِّ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَامَ وَهُوَ سَاجِدٌ حَتَّى ‏ ‏غَطَّ ‏ ‏أَوْ نَفَخَ ثُمَّ قَامَ ‏ ‏يُصَلِّي فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّكَ قَدْ نِمْتَ قَالَ ‏ ‏إِنَّ الْوُضُوءَ لَا يَجِبُ إِلَّا عَلَى مَنْ نَامَ مُضْطَجِعًا فَإِنَّهُ إِذَا اضْطَجَعَ اسْتَرْخَتْ مَفَاصِلُهُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَأَبُو خَالِدٍ ‏ ‏اسْمُهُ ‏ ‏يَزِيدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَابْنِ مَسْعُودٍ ‏ ‏وَأَبِي هُرَيْرَةَ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6fcdf545-bef0-5baa-8f44-a511e4e73be3', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '73', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنَامُونَ ثُمَّ يَقُومُونَ فَيُصَلُّونَ وَلَا يَتَوَضَّئُونَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏قَالَ ‏ ‏و سَمِعْت ‏ ‏صَالِحَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ سَأَلْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ الْمُبَارَكِ ‏ ‏عَمَّنْ نَامَ قَاعِدًا مُعْتَمِدًا فَقَالَ لَا وُضُوءَ عَلَيْهِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَقَدْ رَوَى ‏ ‏حَدِيثَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَوْلَهُ ‏ ‏وَلَمْ يَذْكُرْ فِيهِ ‏ ‏أَبَا الْعَالِيَةِ ‏ ‏وَلَمْ يَرْفَعْهُ ‏ ‏وَاخْتَلَفَ الْعُلَمَاءُ فِي الْوُضُوءِ مِنْ النَّوْمِ فَرَأَى أَكْثَرُهُمْ أَنْ لَا يَجِبَ عَلَيْهِ الْوُضُوءُ إِذَا نَامَ قَاعِدًا أَوْ قَائِمًا حَتَّى يَنَامَ مُضْطَجِعًا ‏ ‏وَبِهِ يَقُولُ ‏ ‏الثَّوْرِيُّ ‏ ‏وَابْنُ الْمُبَارَكِ ‏ ‏وَأَحْمَدُ ‏ ‏قَالَ ‏ ‏بَعْضُهُمْ إِذَا نَامَ حَتَّى غُلِبَ عَلَى عَقْلِهِ وَجَبَ عَلَيْهِ الْوُضُوءُ وَبِهِ يَقُولُ ‏ ‏إِسْحَقُ ‏ ‏و قَالَ ‏ ‏الشَّافِعِيُّ ‏ ‏مَنْ نَامَ قَاعِدًا فَرَأَى رُؤْيَا أَوْ زَالَتْ مَقْعَدَتُهُ ‏ ‏لِوَسَنِ ‏ ‏النَّوْمِ فَعَلَيْهِ الْوُضُوءُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4d008e54-e778-5364-97cf-575b9a790b12', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '74', '‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوُضُوءُ مِمَّا مَسَّتْ النَّارُ وَلَوْ مِنْ ‏ ‏ثَوْرِ ‏ ‏أَقِطٍ ‏ ‏قَالَ ‏ ‏فَقَالَ لَهُ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَنَتَوَضَّأُ مِنْ الدُّهْنِ أَنَتَوَضَّأُ مِنْ ‏ ‏الْحَمِيمِ ‏ ‏قَالَ فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يَا ابْنَ أَخِي إِذَا سَمِعْتَ حَدِيثًا عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَا تَضْرِبْ لَهُ مَثَلًا ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏وأُمِّ سَلَمَةَ ‏ ‏وَزَيْدِ بْنِ ثَابِتٍ ‏ ‏وَأَبِي طَلْحَةَ ‏ ‏وَأَبِي أَيُّوبَ ‏ ‏وَأَبِي مُوسَى ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَقَدْ رَأَى بَعْضُ أَهْلِ الْعِلْمِ الْوُضُوءَ مِمَّا غَيَّرَتْ النَّارُ ‏ ‏وَأَكْثَرُ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ وَمَنْ بَعْدَهُمْ عَلَى تَرْكِ الْوُضُوءِ مِمَّا غَيَّرَتْ النَّارُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3e026f0a-ab54-52af-bdc4-13ea4b5ed50f', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '75', '‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏سَمِعَ ‏ ‏جَابِرًا ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏وَحَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا مَعَهُ فَدَخَلَ عَلَى امْرَأَةٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَذَبَحَتْ لَهُ شَاةً ‏ ‏فَأَكَلَ وَأَتَتْهُ ‏ ‏بِقِنَاعٍ ‏ ‏مِنْ رُطَبٍ فَأَكَلَ مِنْهُ ثُمَّ تَوَضَّأَ لِلظُّهْرِ وَصَلَّى ثُمَّ انْصَرَفَ فَأَتَتْهُ ‏ ‏بِعُلَالَةٍ ‏ ‏مِنْ ‏ ‏عُلَالَةِ ‏ ‏الشَّاةِ فَأَكَلَ ثُمَّ صَلَّى الْعَصْرَ وَلَمْ يَتَوَضَّأْ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏وَأَبِي هُرَيرَةَ ‏ ‏وَابْنِ مَسْعُودٍ ‏ ‏وَأَبِي رَافِعٍ ‏ ‏وَأُمِّ الْحَكَمِ ‏ ‏وَعَمْرِو بْنِ أُمَيَّةَ ‏ ‏وَأُمِّ عَامِرٍ ‏ ‏وَسُوَيْدِ بْنِ النُّعْمَانِ ‏ ‏وَأُمِّ سَلَمَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَلَا يَصِحُّ ‏ ‏حَدِيثُ ‏ ‏أَبِي بَكْرٍ ‏ ‏فِي هَذَا الْبَابِ مِنْ قِبَلِ إِسْنَادِهِ إِنَّمَا رَوَاهُ ‏ ‏حُسَامُ بْنُ مِصَكٍّ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالصَّحِيحُ إِنَّمَا هُوَ عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَكَذَا رَوَاهُ الْحُفَّاظُ ‏ ‏وَرُوِيَ مِنْ غَيْرِ وَجْهٍ عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَوَاهُ ‏ ‏عَطَاءُ بْنُ يَسَارٍ ‏ ‏وَعِكْرِمَةُ ‏ ‏وَمُحَمَّدُ بْنُ عَمْرِو بْنِ عَطَاءٍ ‏ ‏وَعَلِيُّ بْنُ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏وَغَيْرُ وَاحِدٍ عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَمْ يَذْكُرُوا فِيهِ عَنْ ‏ ‏أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏وَهَذَا أَصَحُّ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَالْعَمَلُ عَلَى هَذَا عِنْدَ أَكْثَرِ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ وَمَنْ بَعْدَهُمْ مِثْلِ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏وَابْنِ الْمُبَارَكِ ‏ ‏وَالشَّافِعِيِّ ‏ ‏وَأَحْمَدَ ‏ ‏وَإِسْحَقَ ‏ ‏رَأَوْا تَرْكَ الْوُضُوءِ مِمَّا مَسَّتْ النَّارُ وَهَذَا آخِرُ الْأَمْرَيْنِ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَأَنَّ هَذَا الْحَدِيثَ نَاسِخٌ لِلْحَدِيثِ الْأَوَّلِ ‏ ‏حَدِيثِ الْوُضُوءِ مِمَّا مَسَّتْ النَّارُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c7cd2fa5-489e-5eb1-b100-ee941cc6b431', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '76', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ الرَّازِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْوُضُوءِ مِنْ لُحُومِ الْإِبِلِ فَقَالَ ‏ ‏تَوَضَّئُوا مِنْهَا وَسُئِلَ عَنْ الْوُضُوءِ مِنْ لُحُومِ الْغَنَمِ فَقَالَ لَا تَتَوَضَّئُوا مِنْهَا ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏وَأُسَيْدِ بْنِ حُضَيْرٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَقَدْ رَوَى ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أُسَيْدِ بْنِ حُضَيْرٍ ‏ ‏وَالصَّحِيحُ حَدِيثُ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏وَهُوَ قَوْلُ ‏ ‏أَحْمَدَ ‏ ‏وَإِسْحَقَ ‏ ‏وَرَوَى ‏ ‏عُبَيْدَةُ الضَّبِّيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ الرَّازِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏ذِي الْغُرَّةِ الْجُهَنِيِّ ‏ ‏وَرَوَى ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏عَنْ ‏ ‏الْحَجَّاجِ بْنِ أَرْطَاةَ ‏ ‏فَأَخْطَأَ فِيهِ وَقَالَ فِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أُسَيْدِ بْنِ حُضَيْرٍ ‏ ‏وَالصَّحِيحُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ الرَّازِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏إِسْحَقُ ‏ ‏صَحَّ فِي هَذَا الْبَابِ حَدِيثَانِ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِيثُ ‏ ‏الْبَرَاءِ ‏ ‏وَحَدِيثُ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏وَهُوَ قَوْلُ ‏ ‏أَحْمَدَ ‏ ‏وَإِسْحَقَ ‏ ‏وَقَدْ رُوِيَ عَنْ بَعْضِ أَهْلِ الْعِلْمِ مِنْ التَّابِعِينَ وَغَيْرِهِمْ أَنَّهُمْ لَمْ يَرَوْا الْوُضُوءَ مِنْ لُحُومِ الْإِبِلِ وَهُوَ قَوْلُ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏وَأَهْلِ ‏ ‏الْكُوفَةِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e76d6d09-d36b-5d2f-8ba9-782ca116c8b6', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '77', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْقَطَّانُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏بُسْرَةَ بِنْتِ صَفْوَانَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ مَسَّ ذَكَرَهُ فَلَا يُصَلِّ حَتَّى يَتَوَضَّأَ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏وَأَبِي أَيُّوبَ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏وأَرْوَى ابْنَةِ أُنَيْسٍ ‏ ‏وَعَائِشَةَ ‏ ‏وَجَابِرٍ ‏ ‏وَزَيْدِ بْنِ خَالِدٍ ‏ ‏وَعَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏قَالَ ‏ ‏هَكَذَا ‏ ‏رَوَاهُ ‏ ‏غَيْرُ وَاحِدٍ مِثْلَ هَذَا ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏بُسْرَةَ ‏ ‏وَرَوَى ‏ ‏أَبُو أُسَامَةَ ‏ ‏وَغَيْرُ وَاحِدٍ هَذَا الْحَدِيثَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَرْوَانَ ‏ ‏عَنْ ‏ ‏بُسْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏ ‏حَدَّثَنَا ‏ ‏بِذَلِكَ ‏ ‏إِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏بِهَذَا ‏ ‏وَرَوَى هَذَا الْحَدِيثَ ‏ ‏أَبُو الزِّنَادِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏بُسْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏بِذَلِكَ ‏ ‏عَلِيُّ بْنُ حُجْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏بُسْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏ ‏وَهُوَ قَوْلُ غَيْرِ وَاحِدٍ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ وَبِهِ يَقُولُ ‏ ‏الْأَوْزَاعِيُّ ‏ ‏وَالشَّافِعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏وَأَصَحُّ شَيْءٍ فِي هَذَا الْبَابِ حَدِيثُ ‏ ‏بُسْرَةَ ‏ ‏و قَالَ ‏ ‏أَبُو زُرْعَةَ ‏ ‏حَدِيثُ ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏فِي هَذَا الْبَابِ ‏ ‏صَحِيحٌ ‏ ‏وَهُوَ حَدِيثُ ‏ ‏الْعَلَاءِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏عَنْ ‏ ‏عَنْبَسَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏و قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏لَمْ يَسْمَعْ ‏ ‏مَكْحُولٌ ‏ ‏مِنْ ‏ ‏عَنْبَسَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏وَرَوَى ‏ ‏مَكْحُولٌ ‏ ‏عَنْ رَجُلٍ عَنْ ‏ ‏عَنْبَسَةَ ‏ ‏غَيْرَ هَذَا الْحَدِيثِ ‏ ‏وَكَأَنَّهُ لَمْ يَرَ هَذَا الْحَدِيثَ صَحِيحًا ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
