insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e941e417-28f9-57a0-bfe3-5c98f886ddb6', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '79', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏وَهَنَّادٌ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏وَأَحْمَدُ بْنُ مَنِيعٍ ‏ ‏وَمَحْمُودُ بْنُ غَيْلَانَ ‏ ‏وَأَبُو عَمَّارٍ الْحُسَيْنُ بْنُ حُرَيْثٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبَّلَ بَعْضَ نِسَائِهِ ثُمَّ خَرَجَ إِلَى الصَّلَاةِ وَلَمْ يَتَوَضَّأْ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏مَنْ هِيَ إِلَّا أَنْتِ قَالَ فَضَحِكَتْ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَقَدْ رُوِيَ نَحْوُ هَذَا عَنْ غَيْرِ وَاحِدٍ مِنْ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ وَهُوَ قَوْلُ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏وَأَهْلِ ‏ ‏الْكُوفَةِ ‏ ‏قَالُوا لَيْسَ فِي الْقُبْلَةِ وُضُوءٌ ‏ ‏و قَالَ ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏وَالْأَوْزَاعِيُّ ‏ ‏وَالشَّافِعِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏وَإِسْحَقُ ‏ ‏فِي الْقُبْلَةِ وُضُوءٌ وَهُوَ قَوْلُ غَيْرِ وَاحِدٍ مِنْ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ وَإِنَّمَا تَرَكَ أَصْحَابُنَا حَدِيثَ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي هَذَا لِأَنَّهُ لَا يَصِحُّ عِنْدَهُمْ لِحَالِ الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏و سَمِعْت ‏ ‏أَبَا بَكْرٍ الْعَطَّارَ الْبَصْرِيَّ ‏ ‏يَذْكُرُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ الْمَدِينِيِّ ‏ ‏قَالَ ‏ ‏ضَعَّفَ ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْقَطَّانُ ‏ ‏هَذَا الْحَدِيثَ جِدًّا وَقَالَ ‏ ‏هُوَ شِبْهُ لَا شَيْءَ ‏ ‏قَالَ ‏ ‏و سَمِعْت ‏ ‏مُحَمَّدَ بْنَ إِسْمَعِيلَ ‏ ‏يُضَعِّفُ هَذَا الْحَدِيثَ ‏ ‏و قَالَ ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏لَمْ يَسْمَعْ مِنْ ‏ ‏عُرْوَةَ ‏ ‏وَقَدْ رُوِيَ عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبَّلَهَا وَلَمْ يَتَوَضَّأْ ‏ ‏وَهَذَا ‏ ‏لَا يَصِحُّ ‏ ‏أَيْضًا ‏ ‏وَلَا نَعْرِفُ ‏ ‏لِإِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏سَمَاعًا مِنْ ‏ ‏عَائِشَةَ ‏ ‏وَلَيْسَ يَصِحُّ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي هَذَا الْبَابِ شَيْءٌ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('91993e52-a1f4-510d-ae7c-609425e4102c', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '80', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُبَيْدَةَ بْنُ أَبِي السَّفَرِ وَهُوَ أَحْمَدُ بْنُ عَبْدِ اللَّهِ الْهَمْدَانِيُّ الْكُوفِيُّ ‏ ‏وَإِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏قَالَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَقَالَ ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏حُسَيْنٍ الْمُعَلِّمِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَمْرٍو الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏يَعِيشَ بْنِ الْوَلِيدِ الْمَخْزُومِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاءَ فَأَفْطَرَ فَتَوَضَّأَ ‏ ‏فَلَقِيتُ ‏ ‏ثَوْبَانَ ‏ ‏فِي مَسْجِدِ ‏ ‏دِمَشْقَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَقَالَ صَدَقَ أَنَا صَبَبْتُ لَهُ وَضُوءَهُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏و قَالَ ‏ ‏إِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏مَعْدَانُ بْنُ طَلْحَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَابْنُ أَبِي طَلْحَةَ ‏ ‏أَصَحُّ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَقَدْ رَأَى غَيْرُ وَاحِدٍ مِنْ أَهْلِ الْعِلْمِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَغَيْرِهِمْ مِنْ التَّابِعِينَ الْوُضُوءَ مِنْ الْقَيْءِ ‏ ‏وَالرُّعَافِ ‏ ‏وَهُوَ قَوْلُ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏وَابْنِ الْمُبَارَكِ ‏ ‏وَأَحْمَدَ ‏ ‏وَإِسْحَقَ ‏ ‏و قَالَ ‏ ‏بَعْضُ أَهْلِ الْعِلْمِ لَيْسَ فِي الْقَيْءِ ‏ ‏وَالرُّعَافِ ‏ ‏وُضُوءٌ وَهُوَ قَوْلُ ‏ ‏مَالِكٍ ‏ ‏وَالشَّافِعِيِّ ‏ ‏وَقَدْ جَوَّدَ ‏ ‏حُسَيْنٌ الْمُعَلِّمُ ‏ ‏هَذَا الْحَدِيثَ وَحَدِيثُ ‏ ‏حُسَيْنٍ ‏ ‏أَصَحُّ شَيْءٍ فِي هَذَا الْبَابِ ‏ ‏وَرَوَى ‏ ‏مَعْمَرٌ ‏ ‏هَذَا الْحَدِيثَ عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏فَأَخْطَأَ فِيهِ فَقَالَ عَنْ ‏ ‏يَعِيشَ بْنِ الْوَلِيدِ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏وَلَمْ يَذْكُرْ فِيهِ ‏ ‏الْأَوْزَاعِيَّ ‏ ‏وَقَالَ عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏وَإِنَّمَا هُوَ 