insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('aa28104a-3a93-56f1-bb81-6cab7950f7b5', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '81', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي فَزَارَةَ ‏ ‏عَنْ ‏ ‏أَبِي زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏سَأَلَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا فِي ‏ ‏إِدَاوَتِكَ ‏ ‏فَقُلْتُ ‏ ‏نَبِيذٌ ‏ ‏فَقَالَ ‏ ‏تَمْرَةٌ طَيِّبَةٌ وَمَاءٌ طَهُورٌ قَالَ فَتَوَضَّأَ مِنْهُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَإِنَّمَا رُوِيَ هَذَا الْحَدِيثُ عَنْ ‏ ‏أَبِي زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو زَيْدٍ ‏ ‏رَجُلٌ مَجْهُولٌ عِنْدَ أَهْلِ الْحَدِيثِ لَا تُعْرَفُ لَهُ رِوَايَةٌ غَيْرُ هَذَا الْحَدِيثِ ‏ ‏وَقَدْ رَأَى بَعْضُ أَهْلِ الْعِلْمِ الْوُضُوءَ ‏ ‏بِالنَّبِيذِ ‏ ‏مِنْهُمْ ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏وَغَيْرُهُ ‏ ‏و قَالَ ‏ ‏بَعْضُ أَهْلِ الْعِلْمِ لَا يُتَوَضَّأُ ‏ ‏بِالنَّبِيذِ ‏ ‏وَهُوَ قَوْلُ ‏ ‏الشَّافِعِيِّ ‏ ‏وَأَحْمَدَ ‏ ‏وَإِسْحَقَ ‏ ‏و قَالَ ‏ ‏إِسْحَقُ ‏ ‏إِنْ ابْتُلِيَ رَجُلٌ بِهَذَا فَتَوَضَّأَ ‏ ‏بِالنَّبِيذِ ‏ ‏وَتَيَمَّمَ أَحَبُّ إِلَيَّ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَقَوْلُ مَنْ يَقُولُ لَا يُتَوَضَّأُ ‏ ‏بِالنَّبِيذِ ‏ ‏أَقْرَبُ إِلَى الْكِتَابِ وَأَشْبَهُ لِأَنَّ اللَّهَ تَعَالَى قَالَ ‏ { ‏فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا ‏ ‏صَعِيدًا ‏ ‏طَيِّبًا ‏}', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
