insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cafb702d-1249-5873-8ed2-7ecb862b8c63', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '84', '‏ ‏حَدَّثَنَا ‏ ‏سَوَّارُ بْنُ عَبْدِ اللَّهِ الْعَنْبَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْمُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏قَال سَمِعْتُ ‏ ‏أَيُّوبَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يُغْسَلُ الْإِنَاءُ إِذَا ‏ ‏وَلَغَ ‏ ‏فِيهِ الْكَلْبُ سَبْعَ مَرَّاتٍ أُولَاهُنَّ أَوْ أُخْرَاهُنَّ بِالتُّرَابِ وَإِذَا ‏ ‏وَلَغَتْ ‏ ‏فِيهِ الْهِرَّةُ غُسِلَ مَرَّةً ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَهُوَ قَوْلُ ‏ ‏الشَّافِعِيِّ ‏ ‏وَأَحْمَدَ ‏ ‏وَإِسْحَقَ ‏ ‏وَقَدْ رُوِيَ هَذَا الْحَدِيثُ مِنْ غَيْرِ وَجْهٍ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَ هَذَا وَلَمْ يُذْكَرْ فِيهِ إِذَا ‏ ‏وَلَغَتْ ‏ ‏فِيهِ الْهِرَّةُ غُسِلَ مَرَّةً ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7d6b8de2-f50f-5df9-9a2b-fe2e72dd35ef', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '85', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ مُوسَى الْأَنْصَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مَعْنٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏إِسْحَقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدَةَ بِنْتِ عُبَيْدِ بْنِ رِفَاعَةَ ‏ ‏عَنْ ‏ ‏كَبْشَةَ بِنْتِ كَعْبِ بْنِ مَالِكٍ ‏ ‏وَكَانَتْ عِنْدَ ‏ ‏ابْنِ أَبِي قَتَادَةَ ‏ ‏أَنَّ ‏ ‏أَبَا قَتَادَةَ ‏ ‏دَخَلَ عَلَيْهَا قَالَتْ فَسَكَبْتُ لَهُ وَضُوءًا قَالَتْ فَجَاءَتْ هِرَّةٌ تَشْرَبُ ‏ ‏فَأَصْغَى ‏ ‏لَهَا الْإِنَاءَ حَتَّى شَرِبَتْ قَالَتْ ‏ ‏كَبْشَةُ ‏ ‏فَرَآنِي أَنْظُرُ إِلَيْهِ فَقَالَ أَتَعْجَبِينَ يَا بِنْتَ أَخِي فَقُلْتُ نَعَمْ قَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّهَا لَيْسَتْ بِنَجَسٍ إِنَّمَا هِيَ مِنْ ‏ ‏الطَّوَّافِينَ ‏ ‏عَلَيْكُمْ ‏ ‏أَوْ الطَّوَّافَاتِ ‏ ‏وَقَدْ رَوَى بَعْضُهُمْ عَنْ ‏ ‏مَالِكٍ ‏ ‏وَكَانَتْ عِنْدَ ‏ ‏أَبِي قَتَادَةَ ‏ ‏وَالصَّحِيحُ ‏ ‏ابْنُ أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَهُوَ قَوْلُ أَكْثَرِ الْعُلَمَاءِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ وَمَنْ بَعْدَهُمْ مِثْلِ ‏ ‏الشَّافِعِيِّ ‏ ‏وَأَحْمَدَ ‏ ‏وَإِسْحَقَ ‏ ‏لَمْ يَرَوْا ‏ ‏بِسُؤْرِ ‏ ‏الْهِرَّةِ بَأْسًا وَهَذَا أَحَسَنُ شَيْءٍ رُوِيَ فِي هَذَا الْبَابِ ‏ ‏وَقَدْ جَوَّدَ ‏ ‏مَالِكٌ ‏ ‏هَذَا الْحَدِيثَ عَنْ ‏ ‏إِسْحَقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏وَلَمْ يَأْتِ بِهِ أَحَدٌ أَتَمَّ مِنْ ‏ ‏مَالِكٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2a0399b5-72d0-545c-bcf0-8fe38a860258', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '86', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏بَالَ ‏ ‏جَرِيرُ بْنُ عَبْدِ اللَّهِ ‏ ‏ثُمَّ ‏ ‏تَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ فَقِيلَ لَهُ أَتَفْعَلُ هَذَا قَالَ وَمَا يَمْنَعُنِي وَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُهُ ‏ ‏قَالَ ‏ ‏إِبْرَاهِيمُ ‏ ‏وَكَانَ يُعْجِبُهُمْ حَدِيثُ ‏ ‏جَرِيرٍ ‏ ‏لِأَنَّ إِسْلَامَهُ كَانَ بَعْدَ نُزُولِ ‏ ‏الْمَائِدَةِ ‏ ‏هَذَا قَوْلُ ‏ ‏إِبْرَاهِيمَ ‏ ‏يَعْنِي كَانَ يُعْجِبُهُمْ ‏ ‏قَالَ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏وَعَلِيٍّ ‏ ‏وَحُذَيْفَةَ ‏ ‏وَالْمُغِيرَةِ ‏ ‏وَبِلَالٍ ‏ ‏وَسَعْدٍ ‏ ‏وَأَبِي أَيُّوبَ ‏ ‏وَسَلْمَانَ ‏ ‏وَبُرَيْدَةَ ‏ ‏وَعَمْرِو بْنِ أُمَيَّةَ ‏ ‏وَأَنَسٍ ‏ ‏وَسَهْلِ بْنِ سَعْدٍ ‏ ‏وَيَعْلَى بْنِ مُرَّةَ ‏ ‏وَعُبَادَةَ بْنِ الصَّامِتِ ‏ ‏وَأُسَامَةَ بْنِ شَرِيكٍ ‏ ‏وَأَبِي أُمَامَةِ ‏ ‏وَجَابِرٍ ‏ ‏وَأُسَامَةَ بْنِ زَيْدٍ ‏ ‏وَابْنِ عُبَادَةَ ‏ ‏وَيُقَالُ ‏ ‏ابْنُ عِمَارَةَ ‏ ‏وَأُبَيُّ بْنُ عِمَارَةَ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَحَدِيثُ ‏ ‏جَرِيرٍ ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7c970143-9231-5ad5-b2f6-43a7da90c1bc', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '87', '‏ ‏وَيُرْوَى عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏جَرِيرَ بْنَ عَبْدِ اللَّهِ ‏ ‏تَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ فَقُلْتُ لَهُ فِي ذَلِكَ فَقَالَ رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ فَقُلْتُ لَهُ أَقَبْلَ ‏ ‏الْمَائِدَةِ ‏ ‏أَمْ بَعْدَ ‏ ‏الْمَائِدَةِ ‏ ‏فَقَالَ مَا أَسْلَمْتُ إِلَّا بَعْدَ ‏ ‏الْمَائِدَةِ ‏ ‏حَدَّثَنَا ‏ ‏بِذَلِكَ ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ زِيَادٍ التِّرْمِذِيُّ ‏ ‏عَنْ ‏ ‏مُقَاتِلِ بْنِ حَيَّانَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏وَرَوَى ‏ ‏بَقِيَّةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ أَدْهَمَ ‏ ‏عَنْ ‏ ‏مُقَاتِلِ بْنِ حَيَّانَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏وَهَذَا حَدِيثٌ مُفَسَّرٌ لِأَنَّ بَعْضَ مَنْ أَنْكَرَ الْمَسْحَ عَلَى الْخُفَّيْنِ تَأَوَّلَ أَنَّ مَسْحَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْخُفَّيْنِ كَانَ قَبْلَ نُزُولِ ‏ ‏الْمَائِدَةِ ‏ ‏وَذَكَرَ ‏ ‏جَرِيرٌ ‏ ‏فِي حَدِيثِهِ أَنَّهُ رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسَحَ عَلَى الْخُفَّيْنِ بَعْدَ نُزُولِ ‏ ‏الْمَائِدَةِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2ff406f4-61b1-5559-ba36-4f202463decf', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '88', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الْجَدَلِيِّ ‏ ‏عَنْ ‏ ‏خُزَيْمَةَ بْنِ ثَابِتٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ سُئِلَ عَنْ ‏ ‏الْمَسْحِ عَلَى الْخُفَّيْنِ فَقَالَ لِلْمُسَافِرِ ثَلَاثَةٌ وَلِلْمُقِيمِ يَوْمٌ ‏ ‏وَذُكِرَ عَنْ ‏ ‏يَحْيَى بْنِ مَعِينٍ ‏ ‏أَنَّهُ صَحَّحَ حَدِيثَ ‏ ‏خُزَيْمَةَ بْنِ ثَابِتٍ ‏ ‏فِي الْمَسْحِ ‏ ‏وَأَبُو عَبْدِ اللَّهِ الْجَدَلِيُّ ‏ ‏اسْمُهُ ‏ ‏عَبْدُ بْنُ عَبْدٍ ‏ ‏وَيُقَالُ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَفِي ‏ ‏الْبَاب ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏وَأَبِي بَكْرَةَ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏وَصَفْوَانَ بْنِ عَسَّالٍ ‏ ‏وَعَوْفِ بْنِ مَالِكٍ ‏ ‏وَابْنِ عُمَرَ ‏ ‏وَجَرِيرٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b8487b81-b85c-59ed-a055-9cb44b240546', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '89', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ عَسَّالٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُنَا إِذَا كُنَّا سَفَرًا أَنْ لَا نَنْزِعَ خِفَافَنَا ثَلَاثَةَ أَيَّامٍ وَلَيَالِيهِنَّ إِلَّا مِنْ جَنَابَةٍ وَلَكِنْ مِنْ ‏ ‏غَائِطٍ ‏ ‏وَبَوْلٍ وَنَوْمٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏هَذَا ‏ ‏حَدِيثٌ حَسَنٌ صَحِيحٌ ‏ ‏وَقَدْ رَوَى ‏ ‏الْحَكَمُ بْنُ عُتَيْبَةَ ‏ ‏وَحَمَّادٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ النَّخَعِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الْجَدَلِيِّ ‏ ‏عَنْ ‏ ‏خُزَيْمَةَ بْنِ ثَابِتٍ ‏ ‏وَلَا يَصِحُّ ‏ ‏قَالَ ‏ ‏عَلِيُّ بْنُ الْمَدِينِيِّ ‏ ‏قَالَ ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏لَمْ يَسْمَعْ ‏ ‏إِبْرَاهِيمُ النَّخَعِيُّ ‏ ‏مِنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الْجَدَلِيِّ ‏ ‏حَدِيثَ الْمَسْحِ ‏ ‏و قَالَ ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏كُنَّا فِي حُجْرَةِ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏وَمَعَنَا ‏ ‏إِبْرَاهِيمُ النَّخَعِيُّ ‏ ‏فَحَدَّثَنَا ‏ ‏إِبْرَاهِيمُ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الْجَدَلِيِّ ‏ ‏عَنْ ‏ ‏خُزَيْمَةَ بْنِ ثَابِتٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْحِ عَلَى الْخُفَّيْنِ ‏ ‏قَالَ ‏ ‏مُحَمَّدُ بْنُ إِسْمَعِيلَ ‏ ‏أَحْسَنُ شَيْءٍ فِي هَذَا الْبَابِ حَدِيثُ ‏ ‏صَفْوَانَ بْنِ عَسَّالٍ الْمُرَادِيِّ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَهُوَ قَوْلُ أَكْثَرِ الْعُلَمَاءِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ وَمَنْ بَعْدَهُمْ مِنْ الْفُقَهَاءِ مِثْلِ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏وَابْنِ الْمُبَارَكِ ‏ ‏وَالشَّافِعِيِّ ‏ ‏وَأَحْمَدَ ‏ ‏وَإِسْحَقَ ‏ ‏قَالُوا يَمْسَحُ الْمُقِيمُ يَوْمًا وَلَيْلَةً وَالْمُسَافِرُ ثَلَاثَةَ أَيَّامٍ وَلَيَالِيهِنَّ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَقَدْ رُوِيَ عَنْ بَعْضِ أَهْلِ الْعِلْمِ أَنَّهُمْ لَمْ يُوَقِّتُوا فِي الْمَسْحِ عَلَى الْخُفَّيْنِ وَهُوَ قَوْلُ ‏ ‏مَالِكِ بْنِ أَنَسٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَالتَّوْقِيتُ أَصَحُّ ‏ ‏وَقَدْ رُوِيَ هَذَا الْحَدِيثُ عَنْ ‏ ‏صَفْوَانَ بْنِ عَسَّالٍ ‏ ‏أَيْضًا مِنْ غَيْرِ حَدِيثِ ‏ ‏عَاصِمٍ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b529c1f3-6f09-5805-811c-d03ab0a8ca64', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '90', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ الدِّمَشْقِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏أَخْبَرَنِي ‏ ‏ثَوْرُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏رَجَاءِ بْنِ حَيْوَةَ ‏ ‏عَنْ ‏ ‏كَاتِبِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسَحَ أَعْلَى الْخُفِّ وَأَسْفَلَهُ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَهَذَا قَوْلُ غَيْرِ وَاحِدٍ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالتَّابِعِينَ وَمَنْ بَعْدَهُمْ مِنْ الْفُقَهَاءِ وَبِهِ يَقُولُ ‏ ‏مَالِكٌ ‏ ‏وَالشَّافِعِيُّ ‏ ‏وَإِسْحَقُ ‏ ‏وَهَذَا ‏ ‏حَدِيثٌ مَعْلُولٌ ‏ ‏لَمْ يُسْنِدْهُ عَنْ ‏ ‏ثَوْرِ بْنِ يَزِيدَ ‏ ‏غَيْرُ ‏ ‏الْوَلِيدِ بْنِ مُسْلِمٍ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏وَسَأَلْتُ ‏ ‏أَبَا زُرْعَةَ ‏ ‏وَمُحَمَّدَ بْنَ إِسْمَعِيلَ ‏ ‏عَنْ هَذَا الْحَدِيثِ فَقَالَا ‏ ‏لَيْسَ بِصَحِيحٍ ‏ ‏لِأَنَّ ‏ ‏ابْنَ الْمُبَارَكِ ‏ ‏رَوَى هَذَا عَنْ ‏ ‏ثَوْرٍ ‏ ‏عَنْ ‏ ‏رَجَاءِ بْنِ حَيْوَةَ ‏ ‏قَالَ حُدِّثْتُ عَنْ كَاتِبِ ‏ ‏الْمُغِيرَةِ ‏ ‏مُرْسَلٌ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَمْ يُذْكَرْ فِيهِ ‏ ‏الْمُغِيرَةُ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2bda7c03-2fea-5d77-a3b7-09541222ee12', '831b808e-1d91-4c7c-bb4d-e886f4a9950c', '91', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حُجْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَى الْخُفَّيْنِ عَلَى ‏ ‏ظَاهِرِهِمَا ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏حَدِيثُ ‏ ‏الْمُغِيرَةِ ‏ ‏حَدِيثٌ حَسَنٌ ‏ ‏وَهُوَ حَدِيثُ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي الزِّنَادِ ‏ ‏عَنْ أَبِيهِ عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ ‏ ‏وَلَا نَعْلَمُ أَحَدًا يَذْكُرُ عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ ‏ ‏عَلَى ‏ ‏ظَاهِرِهِمَا ‏ ‏غَيْرَهُ ‏ ‏وَهُوَ قَوْلُ غَيْرِ وَاحِدٍ مِنْ أَهْلِ الْعِلْمِ وَبِهِ يَقُولُ ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏وَأَحْمَدُ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏وَكَانَ ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏يُشِيرُ ‏ ‏بِعَبْدِ الرَّحْمَنِ بْنِ أَبِي الزِّنَادِ ‏', 'جامع الترمذي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
